/* Types */
/**
 *  One "Linked file gone, copy found" item as "Accept all" names it: the
 *  track and the copy the item suggests.
 */
export type AcceptItem = {
	recordingId: number,
	fileId: number,
};

/**  What "Accept all" did. */
export type AcceptedAll = {
	/**  One operation for every switch; `None` if nothing was switched. */
	operationId: number | null,
	/**  Every Library track that was switched, with its old and new file. */
	switched: SwitchedTrack[],
	/**  The items left in the queue, each with why. */
	skipped: SkippedItem[],
};

/**  What an action recorded. */
export type Acted = {
	/**  The operation to offer Undo for. `None` only if nothing changed. */
	operationId: number | null,
};

/**
 *  Every queued and running job, and the `seq` of the last update already
 *  reflected in it.
 */
export type ActivitySnapshot = {
	seq: number,
	/**  Running jobs first, then queued; each in the order workers take them. */
	jobs: JobUpdate[],
};

/**  What an add is doing. */
export type AddPhase = 
/**
 *  No add has begun, or one has begun and its work hasn't started
 *  (it may be waiting behind another write).
 */
"idle" | 
/**  Judging each track the way "Add to Library" would, before any write. */
"checking" | 
/**  Writing: linking tracks into the Library and putting them in the crate. */
"adding" | 
/**  The last add is over. `done` and `total` are where it got to. */
"done";

/**  A reading of the sink: `done` of `total` tracks, in `phase`. */
export type AddProgressState = {
	phase: AddPhase,
	done: number,
	total: number,
};

/**  What an add did. */
export type AddSummary = {
	/**  Library tracks made. */
	added: number,
	alreadyInLibrary: number,
	waitingInMissing: number,
	waitingForConfirmation: number,
	/**
	 *  The operation that added them, which the top bar's Undo takes back.
	 *  `None` when nothing was added.
	 */
	operationId: number | null,
};

/**
 *  Why an add needs the user's go-ahead first. A code and its numbers; the
 *  words come with the screen.
 */
export type AddWarning = 
/**  The file has the `low bitrate` finding. */
{ code: "lowBitrate"; kbps: number };

/**
 *  What adding tracks to a crate by their track id did (1cB-13, 1cB-23): the
 *  table's rows are tracks. A track outside the Library joins the Library as
 *  a linked Library track in the same operation, so one Undo takes both back.
 */
export type AddedToCrate = {
	/**
	 *  How many tracks joined the crate, those that joined the Library with
	 *  it included.
	 */
	added: number,
	/**  How many of those weren't in the Library: they were added to it too. */
	alsoAddedToLibrary: number,
	/**  How many were in the crate already. */
	alreadyThere: number,
	/**  The tracks outside the Library that couldn't join it, so were left out. */
	leftOut: LeftOutOfCrate,
	/**  The operation this recorded; `None` when nothing was added. */
	operationId: number | null,
};

/**  What adding tracks to a new crate did: the crate, and the add. */
export type AddedToNewCrate = {
	crateId: CrateId,
	/**  The name as stored (trimmed). */
	name: string,
	added: AddedToCrate,
};

/**
 *  What adding tracks to a playlist by their track id did (the same shape
 *  as [`crate::crates::AddedToCrate`]: a table's rows are tracks).
 */
export type AddedToPlaylist = {
	/**  Entries added, those for tracks that joined the Library included. */
	added: number,
	/**  How many of those weren't in the Library: they were added to it too. */
	alsoAddedToLibrary: number,
	/**  The tracks outside the Library that couldn't join it, so were left out. */
	leftOut: LeftOutOfCrate,
	/**  The operation this recorded; `None` when nothing was added. */
	operationId: number | null,
};

/**  Both lists, for the screen. */
export type AfterSendLists = {
	/**
	 *  Whether rekordbox's playlists are known: false until a read made
	 *  since this list existed, so an empty `stale_playlists` isn't read as
	 *  "nothing to delete" when nothing was checked.
	 */
	playlistsChecked: boolean,
	stalePlaylists: StalePlaylist[],
	manualRemovals: ManualRemoval[],
};

/**  How an alias is compared with a spelling. */
export type AliasKind = 
/**  The same text. */
"exact" | 
/**  The same once case and accents are folded. */
"folded";

/**  The app's name, version and bundle ID, as the frontend sees them. */
export type AppInfo = {
	name: string,
	version: string,
	identifier: string,
};

/**
 *  One feature's place in the Library at the last batch: `percentile` is 0
 *  to 100, about the share of the Library's files this one is above in
 *  `code`'s feature.
 */
export type Basis = {
	code: BasisCode,
	percentile: number,
};

/**  What a part of the basis is about. */
export type BasisCode = 
/**
 *  Integrated loudness: the percentile is the share of the Library's
 *  files this one is louder than.
 */
"loudness" | 
/**  Onsets a second: denser than that share. */
"onsets" | 
/**  Spectral flux: moves more than that share. */
"flux" | 
/**  Tempo (folded into the user's range): faster than that share. */
"tempo";

/**  How a batch of Inbox files came in. Stored in `inbox_batch.kind`. */
export type BatchKind = 
/**  Files that landed in the Inbox folder itself. */
"loose" | 
/**  Files that landed in one of its subfolders (a pack, an album). */
"folder" | 
/**  What was in the folder when it was added. Not news. */
"already_there";

/**  A file of a Library track's that is ahead of its linked file, and why. */
export type BetterFile = {
	/**
	 *  The better file: the track's best-ranked one that the user hasn't
	 *  dismissed in Review.
	 */
	fileId: number,
	/**
	 *  The step of the ranking that put it ahead: `onDisk`, `verdict`,
	 *  `playable`, `cutoff`, `decodeErrors` or `format`. Never tags, art, a
	 *  rekordbox link or a place: those don't make a file better.
	 */
	step: BetterStep,
};

/**
 *  The steps of the ranking that can make a file a *better file* for a
 *  Library track: about the audio, or about the file being there at all. A
 *  copy that only has more tags, art, a rekordbox link or a better place
 *  is not a better file (tags and art are picked per field, apart from the
 *  audio), and neither is a tie. These are exactly the steps `better_file`
 *  stores and the frontend receives; the table's `CHECK` (migration 0023)
 *  lists the same six names, and a test holds the two together.
 */
export type BetterStep = "onDisk" | "verdict" | "playable" | "cutoff" | "decodeErrors" | "format";

/**  How a track's tempo relates to the selected track's. */
export type BpmFit = 
/**
 *  `delta` BPM above (positive) or below the selected track's, read the
 *  way `time` says.
 */
{ kind: "delta"; delta: number | null; time: TimeFeel } | 
/**  The track has no BPM. */
{ kind: "noBpm" } | 
/**  The selected track has no BPM. */
{ kind: "noTargetBpm" };

/**  The lowest and highest BPM in a crate. */
export type BpmRange = {
	min: number | null,
	max: number | null,
};

/**
 *  Why a track fills the gap, as data for the screen to word
 *  (`playlists:gap.<code>`). Keys are Camelot (`8A`); the screen shows them
 *  in the user's notation. `from` and `to` are A's and B's values, `via` the
 *  suggested track's; at an end of the playlist one of them is missing.
 */
export type BridgeReason = 
/**  A → B clashes on key; X is a key between: `8A → 9A → 10A`. */
{ code: "keyBridge"; from: string; via: string; to: string } | 
/**  The key fits on every side that has one. */
{ code: "keyFits"; from: string | null; via: string; to: string | null } | 
/**
 *  A → B jumps in tempo; X's tempo sits between (half and double time
 *  read as the closest).
 */
{ code: "bpmStep"; from: number | null; via: number | null; to: number | null } | 
/**  The tempo fits on every side that has one. */
{ code: "bpmFits"; from: number | null; via: number | null; to: number | null } | 
/**  X's energy is near the playlist's target at this place. */
{ code: "energyTarget"; via: number; target: number | null } | 
/**  X's energy, between A's and B's: `5 → 6 → 7`. */
{ code: "energyStep"; from: number | null; via: number; to: number | null };

/**
 *  What a bundle or backup holds, for the confirm screen. The schema and
 *  counts are read from its database, not taken from the manifest.
 */
export type BundleSummary = {
	createdMs: number,
	/**  None for a backup. */
	appVersion: string | null,
	schemaVersion: number,
	counts: Counts,
};

/**  What asking to cancel a job did. */
export type CancelOutcome = 
/**  It hadn't started, and now never will. */
"cancelled" | 
/**  It's running and will stop at its next check. */
"stopping" | 
/**  It had already finished, or there's no such job. */
"not_active";

/**  What adding tracks to a crate, or removing them, did. */
export type Changed = {
	/**  How many tracks were added or removed. */
	changed: number,
	/**
	 *  How many were left alone: already in the crate when adding, not in it
	 *  when removing.
	 */
	skipped: number,
	/**
	 *  The operation this recorded; `None` when nothing changed. Undo is
	 *  offered only for a recorded operation: with none, undo would take
	 *  back an earlier, unrelated one.
	 */
	operationId: number | null,
};

/**  How the user settles a conflict. */
export type Choice = { choice: "keepApp" } | { choice: "keepRekordbox" } | 
/**
 *  A value given by hand. It must fit the field ([`fits`]) and hold no
 *  character XML can't carry; for a crate membership it is
 *  [`membership::IN`] or [`membership::OUT`] (so it is always a side's;
 *  the screen never offers it and the Review command refuses it, since a
 *  crate holds the track or it doesn't). One that is the same value as a
 *  side's is recorded as keeping that side.
 */
{ choice: "edit"; value: string };

/**  Comparing a choice (a key, a crate). */
export type ChoiceOp = "is" | "isNot";

/**  What "Use this file instead" did. */
export type Chosen = {
	/**  The operation to offer Undo for. */
	operationId: number | null,
};

/**  How a rule's conditions combine. */
export type Combine = "all" | "any";

/**
 *  One condition of a rule. A track with no value for the field (no energy,
 *  no BPM, no key, no genre, no rating) matches no condition on it, "is
 *  not" included. Tags are the exception: a track with no tags has none, so
 *  "doesn't have" holds for it. A tag or tag group that was deleted matches
 *  no track, "doesn't have" included; the rule stays readable.
 * 
 *  To add a field: a variant here, its SQL in [`compile::condition`], and
 *  its dropdown in `src/crates/smart/`. Nothing else changes.
 */
export type Condition = 
/**  The energy the track shows, 1 to 10. */
{ field: "energy"; op: NumberOp; value: number; to: number | null } | 
/**
 *  The BPM, in whole beats as rounded. With `halfDouble`, a track at
 *  half or double the BPM matches too.
 */
{ field: "bpm"; op: NumberOp; value: number; to: number | null; halfDouble?: boolean } | 
/**  The key, in Camelot notation (`8A`). Any other text matches nothing. */
{ field: "key"; op: ChoiceOp; value: string } | 
/**  The genre as the track shows it. */
{ field: "genre"; op: TextOp; value: string } | 
/**  The rating in stars, 0 to 5. */
{ field: "rating"; op: NumberOp; value: number; to: number | null } | 
/**  In a hand-made crate (by id). */
{ field: "inCrate"; op: ChoiceOp; crateId: CrateId } | 
/**  Has a tag (by id), or doesn't. */
{ field: "tag"; op: TagOp; tagId: TagId } | 
/**  Has any tag of a tag group (by id), or has none of them. */
{ field: "tagGroup"; op: TagOp; groupId: TagGroupId };

/**  A field with open conflicts. */
export type ConflictField = {
	/**  The rekordbox XML attribute name, e.g. `Rating`. */
	field: string,
	kind: ValueKind,
	/**  How many open conflicts the field has. */
	count: number,
	/**
	 *  For a crate membership: the crate's name inside its folders' names,
	 *  joined with " / " (`conflicts::membership::crate_labels`); `None`
	 *  for any other field.
	 */
	crateName: string | null,
};

/**  A `conflict` row's id. */
export type ConflictId = number;

/**  A page of one field's open conflicts. */
export type ConflictPage = {
	field: string,
	/**  How many open conflicts the field has in all. */
	total: number,
	items: ConflictRow[],
};

export type ConflictProblem = 
/**  The field holds a different value from the one the operation left. */
"changedSince" | 
/**  The row the operation changed or made has been deleted since. */
"rowGone" | 
/**  The row the operation deleted exists again. */
"rowBack" | 
/**
 *  Other rows now reference the row, and undoing would silently delete
 *  or change them through a foreign key.
 */
"referenced" | 
/**
 *  The database's own rules refuse the earlier value now: another row
 *  holds a name that must be unique, or rows that must not lose this
 *  one point at it.
 */
"blocked";

/**  One open conflict, with its three values. */
export type ConflictRow = {
	id: ConflictId,
	track: ConflictTrack,
	field: string,
	kind: ValueKind,
	/**  The app's value; `None` when the app holds no value. */
	app: string | null,
	/**
	 *  rekordbox's value; `None` or empty when its entry has no such
	 *  attribute.
	 */
	rekordbox: string | null,
	/**  What was last sent; `None` when the field was never sent. */
	base: string | null,
};

/**  A track named as Review names tracks. */
export type ConflictTrack = {
	libraryTrack: LibraryTrackId,
	title: string | null,
	artist: string | null,
	/**  The name of the track's linked file, if it has one. */
	fileName: string | null,
};

/**  What copying a rekordbox playlist did. */
export type CopiedFromRekordbox = {
	playlistId: PlaylistId,
	/**  Entries copied, in rekordbox's order. */
	added: number,
	/**
	 *  Entries left out: their track isn't a Library track (or has no
	 *  trusted match to a file).
	 */
	notInLibrary: number,
	operationId: number | null,
};

/**  Which numbers can still change because background work is running. */
export type Counting = {
	/**
	 *  A scan, a tags read or a grouping run is queued or running: the
	 *  tracks, total length, genres (from tags) and All music counts.
	 */
	files: boolean,
	/**
	 *  Rekordbox's data is being read, matched or attached: analyzed and
	 *  genres (from rekordbox).
	 */
	rekordbox: boolean,
	/**  A quality job is queued or running: the low-quality count. */
	quality: boolean,
	/**
	 *  The search index is behind (a track is due): the low-quality, energy,
	 *  genre, missing-tags and missing-art counts, which are read from the
	 *  rows the index job writes.
	 */
	index: boolean,
};

/**  A Library's size in a few numbers. */
export type Counts = {
	tracks: number,
	crates: number,
	playlists: number,
	tags: number,
	musicFolders: number,
};

/**  A crate or a folder, as the Crates screen and the sidebar list it. */
export type Crate = {
	id: CrateId,
	/**  The folder it is in; `None` at the top of the tree. */
	parentId: CrateId | null,
	kind: CrateKind,
	name: string,
	/**
	 *  The tracks in a crate; 0 for a folder. `None` for a smart crate: its
	 *  count is its rule run over the Library, so whoever shows it asks for
	 *  that (a table of the crate, no rows, with the total), not every list.
	 */
	trackCount: number | null,
};

/**  A crate's row id. */
export type CrateId = number;

/**  What a row of the crate tree is. */
export type CrateKind = 
/**  Holds crates and folders, never tracks. */
"folder" | 
/**  A hand-made crate of Library tracks. */
"static" | 
/**  A crate whose tracks come from a rule ([`smart`]). */
"smart";

/**  What the crate view shows under a crate's name. */
export type CrateSummary = {
	/**  The crate's note, if it has one. */
	notes: string | null,
	/**  How many tracks are in the crate. */
	tracks: number,
	/**  `None` when no track has a BPM. */
	bpm: BpmRange | null,
	/**  `None` when no track has an energy. */
	energy: EnergyRange | null,
	/**
	 *  Every different key, as Camelot, in Camelot order; empty when no
	 *  track has a key.
	 */
	keys: string[],
	/**
	 *  The biggest genres, biggest first (at most [`TOP_GENRES`]); empty when
	 *  no track has a genre.
	 */
	genres: string[],
};

/**  A bundle just made. */
export type CreatedBundle = {
	path: string,
	manifest: Manifest,
};

/**  Whether a read began. */
export type DatabaseReadStart = { kind: "started"; job: JobId } | { kind: "refused"; reason: DbFailure };

/**  Why a read didn't happen, or failed. */
export type DbFailure = 
/**  The feature is off. */
"turnedOff" | 
/**  No key has been typed in this run of the app. */
"noKey" | 
/**  The database file isn't there. */
"notFound" | 
/**  It couldn't be read, or copied into staging. */
"cantRead" | 
/**  The key isn't this database's. */
"wrongKey" | 
/**  The file is cut off or damaged. */
"damaged" | 
/**  The file opened, but isn't a rekordbox library. */
"notALibrary" | 
/**  The read was cancelled. */
"stopped";

/**  Which way the energy should go from the chosen track. */
export type Direction = "up" | "same" | "down";

/**  A file the tick-off added for you, or matched and left to you. */
export type DoneForYou = {
	inboxItemId: number,
	fileId: number,
	/**  The file's own name (no folders). */
	fileName: string,
	wishlistId: number,
	wishlistName: string,
	wishItemId: number,
	wishArtist: string,
	wishTitle: string,
	wishVersion: string | null,
	/**  How it matched (a `wishlist:reason.*` key). */
	reason: Reason,
	/**  Added to the Library for you. False: matched, and left to you. */
	added: boolean,
	/**
	 *  Why "Add to Library" refuses it, when it does. None on a match left
	 *  to you: a warning to agree to, or a tick-off undone.
	 */
	refusal: InboxRefusal | null,
};

/**  The lowest and highest energy (1 to 10) in a crate. */
export type EnergyRange = {
	min: number,
	max: number,
};

/**  What setting energy did. */
export type EnergySet = {
	/**  Tracks whose energy is now the one asked for and was not. */
	changed: number,
	/**  Tracks left as they were: they had that energy, or are gone. */
	skipped: number,
	/**  The operation Undo takes back; none if nothing changed. */
	operationId: number | null,
};

/**
 *  Where a shown energy comes from, in the order they rank
 *  ([`crate::overview::energy_source_order!`]).
 */
export type EnergySource = 
/**  Set by the user. */
"user" | 
/**  Mixed In Key's. */
"mik";

/**  The energy the app suggests for a track. */
export type EnergySuggestion = {
	/**  1 to 10. */
	value: number,
	basis: Basis[],
};

/**  What rekordbox holds for a Library track: the entry it is sent as. */
export type EntryFacts = {
	/**  How many cues (hot cues and memory cues). */
	cues: number,
	/**  Stars, 0 to 5. */
	stars: number,
	plays: number,
};

/**
 *  What went wrong, in terms the user can act on. Each kind has one
 *  message in the locale files.
 */
export type ErrorKind = 
/**  The database was busy with another write for too long. */
"busy" | 
/**  The disk holding the app data folder is full. */
"diskFull" | 
/**  The app data folder can't be written (read-only, or no permission). */
"cannotWrite" | 
/**  The database file is damaged, or isn't a database. */
"damaged" | 
/**  Any other database failure. */
"database" | 
/**  The database writer has stopped; only a restart brings it back. */
"stopped" | 
/**  A bug or an impossible state: the app did something it shouldn't. */
"internal" | 
/**  The path given as a music folder isn't a folder that exists. */
"notAFolder" | 
/**
 *  The path can't be stored as a music folder: not a full path from a
 *  drive or share, a name Windows doesn't allow, or an unreadable drive.
 */
"badPath" | 
/**  That folder is already a music folder. */
"alreadyAdded" | 
/**  The folder is inside the existing music folder `musicFolder`. */
"insideMusicFolder" | 
/**  The folder contains the existing music folder `musicFolder`. */
"containsMusicFolder" | 
/**  There's no music folder with that id. */
"musicFolderNotFound" | 
/**
 *  Tracks, Library tracks or relinks still use files in the music
 *  folder, so it can't be removed.
 */
"musicFolderInUse" | 
/**  A music folder can only be pointed at a new place while it is missing. */
"relocateNotMissing" | 
/**  The new place is inside, or around, the music folder `musicFolder`. */
"relocateOverlaps" | 
/**  The folder has no known files to recognise it by (never scanned). */
"relocateNoKnownFiles" | 
/**
 *  Only `found` of the `checked` files known in the folder are at the
 *  new place, at the same paths and sizes.
 */
"relocateTooFewFiles" | 
/**  The rekordbox export isn't a file that exists. */
"rekordboxXmlNotFound" | 
/**  The file isn't a rekordbox collection export. */
"notRekordboxXml" | 
/**  No rekordbox export has been chosen yet. */
"noRekordboxXml" | 
/**
 *  The newest rekordbox read is from its database, and a send needs an
 *  XML export (ROADMAP 2.7).
 */
"sendNeedsExport" | 
/**
 *  An XML export is older than the newest read of rekordbox's database,
 *  and reading it would replace that read. Both times are UTC, ISO 8601.
 */
"xmlOlderThanDatabaseRead" | 
/**  There's no track with that id to add to the Library. */
"libraryTrackNotFound" | 
/**  The track has no file to link a Library track to. */
"libraryNoFile" | 
/**  The file the Library track would link to isn't on disk. */
"libraryFileMissing" | 
/**
 *  The track's match to a rekordbox track is only probable, and can't
 *  be confirmed yet.
 */
"libraryMatchNotConfirmed" | 
/**  There's no crate with that id. */
"crateNotFound" | 
/**  The crate's name is empty. */
"crateNameEmpty" | 
/**
 *  Another crate already has the name (names that differ only in letter
 *  case or trailing space count as the same); `name` is that crate's.
 */
"crateNameTaken" | 
/**  The name has a character that can't be sent to rekordbox. */
"crateNameUnsendable" | 
/**  A crate's note is longer than a note can be. */
"crateNotesTooLong" | 
/**  There's no folder with that id (the crate refusals above, for a folder). */
"folderNotFound" | 
/**  The folder's name is empty. */
"folderNameEmpty" | 
/**
 *  Another crate or folder in the folder already has the name; `name` is
 *  that one's.
 */
"folderNameTaken" | 
/**  There is no tag group with that id. */
"tagGroupNotFound" | 
/**  There is no tag with that id. */
"tagNotFound" | 
/**  A tag or group name is empty. */
"tagNameEmpty" | 
/**  Another tag (or group) already has the name; `name` is that one's. */
"tagNameTaken" | 
/**  The tag name has a character that can't be sent to rekordbox. */
"tagNameUnsendable" | 
/**  A colour isn't `#rrggbb`. */
"tagColourInvalid" | 
/**  A crate or folder was to go where there is no folder. */
"crateNotAFolder" | 
/**  A folder was to go inside itself or one of its own subfolders. */
"crateMoveIntoItself" | 
/**  The folders would nest deeper than a send can write. */
"crateTooDeep" | 
/**
 *  A smart crate's rule has more conditions, or longer text, than a
 *  rule holds.
 */
"smartRuleTooLong" | 
/**  The Review item was answered already, or isn't in the queue any more. */
"reviewItemGone" | 
/**
 *  A decision is remembered by what a file holds, and the file hasn't
 *  been hashed yet.
 */
"reviewNoAudioKnown" | 
/**  The linked file is on disk after all, so it isn't switched. */
"reviewSwitchLinkedOnDisk" | 
/**  The file to switch to isn't a file of the track. */
"reviewSwitchNotInTrack" | 
/**  The file to switch to is gone from disk itself. */
"reviewSwitchTargetGone" | 
/**  Another Library track is linked to the file to switch to. */
"reviewSwitchTargetLinked" | 
/**
 *  rekordbox's entry on the file to switch to is the one another Library
 *  track is sent as.
 */
"reviewSwitchEntryTaken" | 
/**  Two tracks to merge are linked as versions, and versions never merge. */
"reviewMergeLinkedVersions" | 
/**  What the switch means in rekordbox changed since the item was shown. */
"reviewSwitchChanged" | 
/**
 *  The file to split off holds the very same audio as a file it would be
 *  split from: such files are always one track.
 */
"reviewSameAudio" | 
/**
 *  The copies a split would take along are the files of two Library
 *  tracks, which are never made one track by a split.
 */
"reviewSplitTwoLibraryTracks" | 
/**
 *  "Use this file instead" was asked for a file of a track in the Library,
 *  whose linked file is pinned.
 */
"hiddenChoiceInLibrary" | 
/**
 *  "Use this file instead" was asked for a file that is no longer an extra
 *  copy on disk, or that holds the very same bytes as the file shown.
 */
"hiddenChoiceChanged" | 
/**  The conflict was settled or withdrawn already, so it isn't open. */
"conflictGone" | 
/**  The value given by hand isn't a value of the conflict's field. */
"conflictBadValue" | 
/**
 *  The number of open conflicts a bulk resolve was asked about is not the
 *  number there is now.
 */
"conflictsChanged" | 
/**  The genre or alias was not found (it was removed meanwhile). */
"genreNotFound" | 
/**  A genre or alias name is empty once trimmed. */
"genreNameEmpty" | 
/**  Another genre has the name (ignoring case and accents); `name` is that genre's. */
"genreNameTaken" | 
/**  A genre was to go inside itself or one of its own descendants. */
"genreMoveIntoItself" | 
/**  The spelling is already a genre's name or an alias; `name` is the genre it goes to. */
"genreAliasTaken" | 
/**  A genre name or alias is longer than 200 characters. */
"genreTextTooLong" | 
/**  There is no playlist with that id (it was deleted meanwhile). */
"playlistNotFound" | 
/**  The entry to move tracks before is no longer in the playlist. */
"playlistEntryNotFound" | 
/**  "Keep this order" named other entries than the playlist has now. */
"playlistOrderStale" | 
/**  A playlist name is empty once trimmed. */
"playlistNameEmpty" | 
/**  Another playlist (or the Tags folder) has the name; `name` is that one's. */
"playlistNameTaken" | 
/**  The playlist name has a character that can't be sent to rekordbox. */
"playlistNameUnsendable" | 
/**  The newest rekordbox read has no playlist with entries at that path. */
"rekordboxPlaylistNotFound" | 
/**  The picked file isn't a tracklist-pro bundle (not our zip, entries or schema). */
"bundleNotOurs" | 
/**  A bundle entry unpacks to more than the app accepts. */
"bundleTooLarge" | 
/**  The bundle's database is damaged. */
"bundleDamaged" | 
/**  The bundle was made by a newer version of the app. */
"bundleNewer" | 
/**  Confirm was asked with no bundle or backup staged. */
"bundleNothingStaged" | 
/**  The backup to restore is gone. */
"bundleBackupNotFound" | 
/**  The bundle to save isn't one the app made. */
"saveNotABundle" | 
/**  The chosen file name doesn't end in .zip. */
"saveNotZip" | 
/**  The chosen name has a colon, a device name, or ends in a dot or space. */
"saveBadName" | 
/**  A file or folder is already at the chosen place; nothing is replaced. */
"saveExists" | 
/**  The chosen folder doesn't exist. */
"saveFolderMissing" | 
/**  The chosen folder, or one above it, is a link or isn't a folder. */
"saveFolderNotPlain" | 
/**  The chosen place is inside a music folder. */
"saveInMusicFolder" | 
/**  The chosen place is inside the app's own folder. */
"saveInAppData" | 
/**  The chosen drive looks like a rekordbox gig stick. */
"saveGigStick" | 
/**  The chosen place is inside rekordbox's data folder. */
"saveInRekordboxFolder";

/**
 *  A value filled into an error message: data (a name, a path, a count),
 *  never prose. Numbers stay numbers so the frontend formats them. They're
 *  32-bit whole numbers, so every one is exact in a TypeScript `number` and
 *  there's no NaN to send; add a finite decimal when a message needs one.
 */
export type ErrorParam = string | number;

/**
 *  What happened. A fixed list: new kinds are added here, never built from
 *  text.
 */
export type EventKind = "jobStarted" | "jobFinished" | "jobFailed" | "jobCancelled" | "rekordboxReadOk" | "rekordboxReadFailed" | "databaseReadOk" | "databaseReadFailed" | "sendPrepared" | "sendDone" | "sendRefused" | 
/**
 *  The app started: `ms` is how long setup took, `count` how many jobs
 *  an earlier run left running.
 */
"startup" | 
/**
 *  Startup asked the stages what is due: `ms` is how long it took,
 *  `count` how many stages couldn't be asked.
 */
"startupAsked" | 
/**
 *  A confirmed import or restore of a Library couldn't be finished at
 *  startup; the Library in place opened instead (4.1).
 */
"libraryNotReplaced";

/**  The log, newest first, for the Diagnostics screen. */
export type EventLogView = {
	events: LogEvent[],
	/**
	 *  Events that couldn't be written to the log's file this run. They
	 *  are still in this list until the app closes.
	 */
	lostWrites: number,
};

/**
 *  Why something failed, as a code. A fixed list, so no message text can be
 *  stored in its place; each source of failures converts into it.
 */
export type EventReason = 
/**  The job's handler returned an error. */
"jobFailed" | 
/**  The job's handler panicked. */
"panicked" | 
/**  This build has no handler for the job's kind. */
"noHandler" | 
/**  This build doesn't know the job's kind. */
"unknownKind" | "notFound" | "cantRead" | "damaged" | "notAnExport" | "turnedOff" | "noKey" | "wrongKey" | "notALibrary" | "stopped" | "readFailed" | "cancelled" | "noPreflight" | "exportChanged" | "libraryChanged" | "notSendable" | "notConfirmed" | "exportOlderThanLastSend" | "cantWrite" | "cantRecord" | "internal" | 
/**  A file was already where the old Library is set aside. */
"fileInTheWay";

/**  An export file found on disk. */
export type ExportFile = {
	path: string,
	/**  The file name, for showing. */
	name: string,
	/**  Milliseconds since the Unix epoch. */
	modifiedMs: number,
};

/**  The export a preflight was made from. */
export type ExportRead = {
	path: string,
	/**
	 *  When rekordbox saved it: the file's modified time, in milliseconds
	 *  since the Unix epoch.
	 */
	modifiedMs: number,
	/**  When the app read it (UTC, ISO 8601). */
	readAt: string,
	/**
	 *  Tracks in the export that couldn't be read. Above 0, the send
	 *  needs an explicit confirm ([`Preflight::needs_confirm`]).
	 */
	notStored: number,
};

/**  Why a read failed, in terms the user can act on. */
export type FailureReason = 
/**  The file isn't there any more. */
"notFound" | 
/**  The file couldn't be opened or read. */
"cantRead" | 
/**  Not well-formed: cut off, or damaged. Export again. */
"damaged" | 
/**  Well-formed XML, but not a rekordbox collection export. */
"notAnExport";

/**
 *  An optional feature (ROADMAP §1.1, CLAUDE.md "Network and privacy"): off
 *  until the user turns it on. Stored in `setting` as JSON `true` or
 *  `false` under `feature_<name>`; no row means off. Like the other
 *  settings, a write is not an operation in the log.
 */
export type Feature = 
/**  Wishlists (2.3 to 2.5). */
"wishlist" | 
/**  Reading rekordbox's library database (2.7). */
"rekordboxDatabase" | 
/**
 *  The app's own key estimates, shown as the weakest source of a key:
 *  the owner's test switch (3.7, "Key"), until they reach the bar to be
 *  shown by default.
 */
"localKey";

/**
 *  One field: the value the track shows and the other values the track's
 *  sources hold for it.
 */
export type FieldSources = {
	field: TagField,
	/**
	 *  The value the track shows. `None` when rekordbox knows the track and
	 *  leaves the field blank (a file's tag doesn't stand in for it).
	 */
	shown: SourcedValue | null,
	/**
	 *  Values that differ from the one shown, each naming its file, in the
	 *  order the files are asked.
	 */
	others: SourcedValue[],
};

/**  One track's value of a field. */
export type FieldValue = {
	recordingId: number,
	/**  `None`: the track has no value for the field. */
	value: string | null,
};

/**  The best tracks for a place in a playlist. */
export type FillGapReply = {
	suggestions: GapSuggestion[],
	/**  How many Library tracks were weighed. */
	considered: number,
	/**  The playlist's target energy at this place, if it has a target. */
	target: number | null,
};

/**  The reason a track fits, as facts for the screen to word. */
export type FitReason = {
	key: KeyFit,
	bpm: BpmFit,
};

/**  How a transition fares on one signal. */
export type Flow = "fine" | 
/**  A clash or jump, by the tolerance. */
"clash" | 
/**  One of the two tracks has no value for it. */
"unknown";

/**  What deleting a folder would delete, below the folder itself. */
export type FolderContents = {
	crates: number,
	folders: number,
	/**  Different Library tracks in those crates. They stay in the Library. */
	tracks: number,
};

/**
 *  Why a file's location is fragile. The Library shows each with its
 *  reason (the wording lives in the locale files).
 */
export type FragileReason = "downloads" | "temp" | "external" | "network";

/**  One suggested track and why. */
export type GapSuggestion = {
	/**  The track, as the track table shows it. */
	row: TableRow,
	/**  0 to 100. */
	score: number,
	/**  What gap it fills, strongest first; never empty. */
	reasons: BridgeReason[],
};

/**  The counts for one genre node. */
export type GenreAgreement = {
	/**  The node's name; `None` for the tracks whose genre resolves to none. */
	genre: string | null,
	counts: KeyAgreement,
};

/**  An alias of a genre. */
export type GenreAlias = {
	id: number,
	genreId: number,
	alias: string,
	kind: AliasKind,
};

/**  One genre and how many Library tracks have it. */
export type GenreCount = {
	/**
	 *  The genre as most of its tracks spell it, without outer blanks.
	 *  Capitals don't make a genre of its own.
	 */
	name: string,
	tracks: number,
};

/**  A genre, with the Library tracks the index maps to it. */
export type GenreNode = {
	id: number,
	parentId: number | null,
	name: string,
	tracks: number,
};

/**  The whole taxonomy, nodes in tree order. */
export type GenreTree = {
	nodes: GenreNode[],
	aliases: GenreAlias[],
};

/**
 *  How many hidden files a search matches that its results don't show
 *  already (ROADMAP 1.11, owner decision 2026-10-12): the hidden files of
 *  matching tracks that have no shown file, so are not in the results.
 */
export type HiddenMatches = {
	count: number,
	/**  The index is behind, so the count may be off for a moment. */
	behind: boolean,
};

/**  A window of hidden files. */
export type HiddenPage = {
	total: number | null,
	offset: number,
	rows: HiddenRow[],
	/**  The index job hasn't caught up with some change. */
	behind: boolean,
};

/**  What the Hidden filter is asked for: a window, like the track table's. */
export type HiddenQuery = {
	/**
	 *  Search text (`search::match_expression`); blank filters nothing. A
	 *  file is listed when its track matches.
	 */
	search: string | null,
	/**  Title, Artist or File; any other column, or none, is the title. */
	sort: TableSort | null,
	offset: number,
	/**  At most [`crate::track_table::MAX_WINDOW`]. */
	limit: number,
	withTotal: boolean,
};

/**  One file the app isn't showing. */
export type HiddenRow = {
	fileId: number,
	/**  Its track; `None` for a hidden file the grouping hasn't placed yet. */
	recordingId: number | null,
	why: Why,
	wayBack: WayBack | null,
	/**  The track as the lists name it: its title, else a file's name. */
	track: string,
	artist: string | null,
	/**  This file's name, without its folder. */
	file: string,
	/**  For an extra copy, the name of the file chosen as the track's best. */
	bestFile: string | null,
	/**  For an extra copy: that best file is the one the user chose. */
	bestFileChosen: boolean,
	/**
	 *  For an extra copy: its track is in the Library, so it can't be
	 *  switched to this file (1cB-22).
	 */
	trackInLibrary: boolean,
};

/**  What a history command came to. */
export type HistoryOutcome = 
/**  Done, as one operation (`None` when nothing changed). */
{ outcome: "done"; operationId: number | null; sessionId: number; 
/**  Plays the session holds, and how many of them matched a track. */
plays: number; matched: number; 
/**  Lines of the file that couldn't be read. */
skippedLines: number } | 
/**
 *  Nothing was written. `session_id` names the session it already is,
 *  for [`HistoryRefusal::AlreadyImported`].
 */
{ outcome: "refused"; reason: HistoryRefusal; sessionId: number | null; skippedLines: number };

/**  Why nothing was written. */
export type HistoryRefusal = 
/**  The file couldn't be read. */
"fileUnreadable" | 
/**  The file is over [`m3u8::MAX_BYTES`]. */
"fileTooBig" | 
/**  The file names no play. */
"noPlays" | 
/**  The same plays, in the same order, are already a session. */
"alreadyImported" | "noSuchSession" | 
/**  Not a day of the calendar as `YYYY-MM-DD`. */
"badDate";

/**  What the sidebar badge counts: items still `new` whose file is present. */
export type InboxCount = {
	/**  Arrivals nobody has decided about: the badge. */
	new: number,
	/**
	 *  New items that were already in a folder when it was added. Not in
	 *  `new`.
	 */
	alreadyThere: number,
	/**  The arrivals counted in `new`, by label. They add up to `new`. */
	byLabel: LabelCounts,
	/**  Every Inbox folder. */
	folders: InboxFolder[],
};

/**  Which items [`items`] returns. */
export type InboxFilter = {
	/**  Only items with this status. */
	status?: ItemStatus | null,
	/**
	 *  Only items of this batch. A batch asked for by id is returned
	 *  whatever its kind.
	 */
	batchId?: number | null,
	/**
	 *  Also the items that were already in a folder when it was added.
	 *  Left out unless asked for: they aren't arrivals.
	 */
	includeAlreadyThere?: boolean,
	/**  Only items with this label. */
	label?: Label | null,
};

/**  An Inbox folder, as far as intake is concerned. */
export type InboxFolder = {
	musicFolderId: number,
	/**
	 *  Its first look (the baseline: what was there is not news) isn't
	 *  taken yet, so nothing arrives from it. It waits for a walk that
	 *  lists everything, or the third that doesn't.
	 */
	waitingForFirstLook: boolean,
};

/**  One file in the Inbox, as the frontend sees it. */
export type InboxItem = {
	id: number,
	/**  The `file` row (file.id). */
	fileId: number,
	/**
	 *  The file's own name (the last part of its stored relative path), not
	 *  a full path.
	 */
	fileName: string,
	musicFolderId: number,
	batchId: number,
	batchKind: BatchKind,
	/**  The subfolder of a `folder` batch, relative to the music folder. */
	batchLabel: string | null,
	status: ItemStatus,
	/**  When it counted as arrived (UTC, ISO 8601). */
	arrivedAt: string,
	decidedAt: string | null,
	/**
	 *  The file is on disk as of the last walk. A file gone from disk keeps
	 *  its item.
	 */
	present: boolean,
	/**
	 *  A OneDrive placeholder: its content isn't on this device, and
	 *  nothing reads it without the user's opt-in.
	 */
	onlineOnly: boolean,
	/**  What the file is to the user, worked out now (see [`labels`]). */
	label: Label,
	/**  Why, as an i18n key with parameters. */
	reason: Reason,
	/**  The Library track the label is about, if it is about one. */
	libraryTrackId: number | null,
};

/**  What an Inbox action came to. */
export type InboxOutcome = 
/**  Done, as one operation (`None` when nothing changed). */
{ outcome: "done"; operationId: number | null; 
/**  The items it changed. */
items: number[]; 
/**  "Add all" only: the items it left as they were, each with why. */
skipped: Skipped[] } | 
/**  Nothing was written: this item can't be acted on. */
{ outcome: "refused"; itemId: number; reason: InboxRefusal } | 
/**
 *  Nothing was written: adding this item's file needs the user's
 *  go-ahead first. Ask again with it confirmed.
 */
{ outcome: "needsConfirmation"; itemId: number; warning: AddWarning };

/**  Why an item can't be acted on. Nothing was written. */
export type InboxRefusal = 
/**  There is no such item (its folder was removed). */
"itemGone" | 
/**  It was added, hidden or cleared already. */
"alreadyDecided" | 
/**  Its file isn't in a track yet: it is still being identified. */
"notIdentified" | 
/**  Its track is in the Library already (it has its own actions). */
"hasLibraryTrack" | 
/**
 *  Clear is for a file whose track is in the Library, and this one's
 *  isn't.
 */
"noLibraryTrack" | 
/**  The file isn't on disk. */
"fileMissing" | 
/**
 *  rekordbox has this track as another file: linked to this one it
 *  would arrive as a second entry, without the first one's cues.
 */
"inRekordboxAsAnotherFile" | 
/**
 *  The file is the probable match of a rekordbox entry, and nothing
 *  can confirm it yet (`library::match_not_confirmed`).
 */
"matchNotConfirmed" | 
/**  Another item of this add is a file of the same track. */
"sameTrackTwice" | 
/**
 *  The file is the linked file of a Library track: hiding it would take
 *  the Library track's own file out of All music.
 */
"isLibraryFile";

/**
 *  Why a command failed, as the frontend receives it: a kind and the
 *  parameters its message needs. Never error text.
 */
export type IpcError = {
	kind: ErrorKind,
	params: { [key in string]: ErrorParam },
};

/**  What was decided about an Inbox file. Stored in `inbox_item.status`. */
export type ItemStatus = "new" | "not_now" | "hidden" | "added";

/**  A job's row id in the `job` table. */
export type JobId = number;

/**
 *  The kinds of background work (ROADMAP 0.1). Stored in `job.kind` as
 *  [`JobKind::as_str`].
 */
export type JobKind = 
/**  Walk the music folders for audio files (1.1). */
"scan" | 
/**  Read the files' tags and audio properties (1.1 stage 2). */
"read" | 
/**  Hash a file's audio (`audio_hash`). */
"hash" | 
/**  Acoustic fingerprint (1.4). */
"fingerprint" | 
/**
 *  Put files into tracks, and with `decide` in its target, decide
 *  their pairs by the grouping rules first (1.4, 1.5). With `roles` in
 *  its target, rank the files of the tracks that changed and set their
 *  roles (1.7). The targets are `grouping::GroupTarget`.
 */
"group" | 
/**  Estimate BPM, key and energy (3.7). */
"analyze" | 
/**  Run the audio model (3.8). */
"embed" | 
/**  Make a Library copy in another format (2.6). */
"convert" | 
/**  Write an export, e.g. the rekordbox XML (1.9). */
"export" | 
/**  Read rekordbox's XML export into the snapshot (1.2). */
"read_rekordbox" | 
/**  Match rekordbox tracks to files (1.2 relink). */
"relink" | 
/**  Attach rekordbox's BPM and key to tracks (1.2, 1aD-4). */
"attach" | 
/**
 *  Measure a file's spectral cutoff, decoded duration and decode
 *  errors (1.6).
 */
"quality" | 
/**  Compare files' fingerprints to find shared audio (1.4). */
"match" | 
/**
 *  Work out the full-text search index of the tracks that changed
 *  (1.11).
 */
"index" | 
/**
 *  Reduce a file's audio to the peaks its waveform is drawn from
 *  (1.11 "Audio").
 */
"waveform";

/**
 *  Where a job is in its life. Stored in `job.status` as
 *  [`JobStatus::as_str`].
 */
export type JobStatus = 
/**  Waiting for a worker. */
"queued" | 
/**  A worker is doing it. */
"running" | 
/**  Finished its work. */
"done" | 
/**  Stopped with an error, kept in `job.error`. */
"failed" | 
/**  Stopped because it was cancelled. */
"cancelled";

/**
 *  A job changed: it was queued, started, made progress or finished.
 * 
 *  Every update carries `seq`, which rises by one with each change the app
 *  makes to any job. A listener that starts from an [`ActivitySnapshot`]
 *  applies only the updates newer than the snapshot's `seq`, and for each
 *  job only updates newer than the last it applied, so a job never goes
 *  back to an older state.
 */
export type JobUpdate = {
	seq: number,
	id: JobId,
	kind: JobKind,
	status: JobStatus,
	/**  0 to 1, once the job has reported any. */
	progress: number | null,
	/**  Higher runs first. */
	priority: number,
};

/**
 *  Job updates, sent together: the newest update for each job that
 *  changed since the last batch, in `seq` order.
 */
export type JobUpdates = JobUpdate[];

/**  A replaced Library kept in `backups/`. */
export type KeptLibrary = {
	id: string,
	createdMs: number,
	/**  None when it can't be read. */
	counts: Counts | null,
};

/**  How many pairs fell in each kind of agreement. */
export type KeyAgreement = {
	tracks: number,
	exact: number,
	relative: number,
	oneStep: number,
	parallel: number,
	other: number,
};

/**  The whole comparison. */
export type KeyComparison = {
	overall: KeyAgreement,
	/**  By node name; the tracks with no node last. */
	genres: GenreAgreement[],
};

/**  How a track's key relates to the selected track's. */
export type KeyFit = 
/**  The same key. */
{ kind: "same"; key: string } | 
/**  Next to it on the wheel. */
{ kind: "neighbor"; from: string; to: string } | 
/**  Any other key. */
{ kind: "far"; from: string; to: string } | 
/**  The track has no key. */
{ kind: "noKey" } | 
/**  The selected track has no key. */
{ kind: "noTargetKey" };

/**
 *  How keys are shown: one app-wide setting (ROADMAP §1.1), stored in the
 *  `setting` table (see `crate::settings`). Camelot is the default.
 * 
 *  To add a notation (e.g. Open Key, or Serato's or Mixed In Key's
 *  spellings): add a variant here and to [`KeyNotation::ALL`], and a match
 *  arm in [`MusicalKey::format`]. The stored name, the TypeScript type and
 *  the frontend's name table follow from those.
 */
export type KeyNotation = 
/**  `8A`, `12B`. */
"camelot" | 
/**
 *  Conventional key-signature spelling: the enharmonic name with the
 *  fewest sharps or flats (`C#m`, not `Dbm`, which would need 8 flats).
 */
"musical_standard" | 
/**  rekordbox's own spelling, from the rekordbox behavior check. */
"musical_rekordbox" | 
/**  Every black key as a sharp: `C#`, `D#m`, `A#`. */
"musical_sharps" | 
/**  Every black key as a flat: `Db`, `Ebm`, `Bb`. */
"musical_flats";

/**  What an Inbox file is to the user. */
export type Label = 
/**  Not through fingerprint, matching and deciding yet. */
"checking" | 
/**  Its track isn't in the Library, and no version link leads to one. */
"new_to_you" | 
/**  Its track is in the Library, and this file adds nothing. */
"already_have" | 
/**  Its track is in the Library, and this file ranks above the linked one. */
"better_file" | 
/**  Another cut of a track in the Library (Radio Edit of your Extended). */
"other_cut" | 
/**  A rework of a track in the Library. */
"rework";

/**  How many of the `new` arrivals have each label. */
export type LabelCounts = {
	checking: number,
	newToYou: number,
	alreadyHave: number,
	betterFile: number,
	otherCut: number,
	rework: number,
};

/**  The last export read into the snapshot. */
export type LastRead = {
	path: string,
	/**
	 *  The file's modified time when the read began, in milliseconds since
	 *  the Unix epoch.
	 */
	modifiedMs: number,
	/**  When the snapshot was replaced (UTC, ISO 8601). */
	readAt: string,
	summary: SnapshotSummary,
	/**  What was read. Reads stored before there was a choice were XML. */
	source?: ReadSource,
};

/**  A Library track a send leaves out. */
export type LeftOut = {
	track: TrackLabel,
	reason: LeftOutReason,
	/**  The rekordbox field at fault, where the reason names one. */
	attribute: string | null,
};

/**
 *  How many tracks outside the Library were left out of an add to a crate,
 *  by why: the reasons "Add to Library" gives (1.8), which a crate add must
 *  not get around. Each track is counted once, under one reason.
 */
export type LeftOutOfCrate = {
	/**  The track has no file. */
	noFile: number,
	/**  Its file isn't on disk. */
	fileMissing: number,
	/**  Its only rekordbox match is a probable one, not confirmed yet. */
	matchNotConfirmed: number,
	/**
	 *  Its file has the low bitrate finding, which "Add to Library" asks the
	 *  user to agree to; an add to a crate can't ask, so it is added by hand.
	 */
	lowBitrate: number,
};

/**
 *  Why a Library track is left out of a send. A code; the wording is in
 *  the locale file.
 */
export type LeftOutReason = 
/**  It has no linked file. */
"noFile" | 
/**  Its linked file isn't on disk. */
"fileMissing" | 
/**
 *  Its file's path can't be worked out (its drive or folder doesn't
 *  read back).
 */
"noPath" | 
/**  Its path can't be written as a rekordbox `Location`. */
"pathNotSendable" | 
/**
 *  One of its values holds a character XML can't carry
 *  ([`LeftOut::attribute`] names the field).
 */
"unsendableCharacter" | 
/**  An earlier track of this send is the same file. */
"sameFileAsAnother" | 
/**
 *  rekordbox's own entry for it can't be sent back as it is (its
 *  `TrackID` or an attribute is unusable or repeated).
 */
"rekordboxEntry";

/**  What the screens need to know about the Library without its list. */
export type LibrarySummary = {
	/**  How many Library tracks there are. */
	tracks: number,
	/**
	 *  Moves whenever any row the Library list is made of changes (a track
	 *  added, removed, retitled or relinked). Only ever compared with the
	 *  last one seen: for equality, never for order.
	 */
	changeStamp: number,
};

/**  A Library track, with what the Library list shows. */
export type LibraryTrack = {
	id: LibraryTrackId,
	/**  The track (`recording`) it was made from. */
	recordingId: number,
	kind: LibraryTrackKind,
	/**
	 *  The title and artist the list shows: what a send writes for the
	 *  track, else (for the title) the file's name. `None` only when the
	 *  track has neither.
	 */
	title: string | null,
	artist: string | null,
	/**  The linked file. `None` only for a Library track with no file link. */
	file: LinkedFile | null,
	/**
	 *  Why the linked file's location is fragile (Downloads, a temp folder,
	 *  an external or network drive), if it is (1aD-7).
	 */
	fragile: FragileReason | null,
	/**
	 *  Whether the linked file is gone. Kept current by the scan
	 *  (`library_track.source_status`), not worked out when listed.
	 */
	sourceMissing: boolean,
	/**
	 *  How many conflicts with rekordbox are still open for it. Removing
	 *  the track drops them (undo brings them back).
	 */
	openConflicts: number,
	/**  When it was added, UTC ISO-8601. */
	addedAt: string,
	/**
	 *  Another file of the track ranks ahead of the linked file in what the
	 *  audio is, or in being there at all (ROADMAP 1.7, "Better file
	 *  available"). The linked file doesn't change for it: a link only
	 *  follows the same audio ([`follow`]).
	 */
	betterFile: BetterFile | null,
};

/**  A Library track's row id. */
export type LibraryTrackId = number;

/**  What a Library track's audio is. Stored in `library_track.kind`. */
export type LibraryTrackKind = 
/**  It points at an existing file, which is never written. */
"linked" | 
/**  A managed copy in the Library folder (Phase 2, ROADMAP 2.6). */
"copy";

/**  The file a linked Library track plays, as the frontend sees it. */
export type LinkedFile = {
	/**
	 *  The file's id (`file.id`): what the preview player is given to play
	 *  it (1cA-7).
	 */
	id: number,
	/**
	 *  Where the file is, e.g. `E:\DJ Music\a.mp3`: under its volume's
	 *  mount point now, or where that was last seen if the volume is
	 *  offline.
	 */
	path: string,
	/**  The file's name, e.g. `a.mp3`. */
	name: string,
	/**  Whether the last scan found it on disk (`file.present`). */
	present: boolean,
	/**
	 *  Whether its drive is connected now. A file on an unplugged drive
	 *  stays `present`, and its track isn't missing.
	 */
	driveConnected: boolean,
};

/**
 *  One entry of the log. Every field is a number or a fixed list: there is
 *  nowhere to put text. Unknown fields in the file are refused when it is
 *  read back.
 */
export type LogEvent = {
	/**  When, in milliseconds since the Unix epoch. */
	atMs: number,
	kind: EventKind,
	/**  The job's kind, for the job and read events. */
	job: JobKind | null,
	reason: EventReason | null,
	/**  How many, where the kind says what. */
	count: number | null,
	/**  How long it took, in milliseconds. */
	ms: number | null,
};

/**
 *  A crate or playlist that will arrive in rekordbox with entries left out
 *  (their tracks aren't sent). Importing it replaces rekordbox's playlist
 *  of that name, so those entries are lost there (§5.2).
 */
export type LosesEntries = {
	kind: TreeKind,
	/**  The folder names down to it, below `Crates` or `Playlists`. */
	path: string[],
	/**  How many of its entries are left out. */
	lost: number,
	/**  How many entries it has in the app. */
	entries: number,
};

/**  The manifest stored beside the database in a bundle. */
export type Manifest = {
	app: string,
	format: number,
	appVersion: string,
	schemaVersion: number,
	createdMs: number,
	counts: Counts,
};

/**  A track to remove in rekordbox by hand. */
export type ManualRemoval = {
	reason: RemovalReason,
	recordingId: number,
	/**
	 *  What rekordbox shows for it if it has a row at the sent `Location`,
	 *  else the file's tags, else the file's name ([`shown_removed`]).
	 */
	title: string | null,
	artist: string | null,
	/**
	 *  Where it was sent, as Windows writes it, so the user can find it in
	 *  rekordbox; for a track that was never sent, where rekordbox's own
	 *  entry for it is. `None` if the sent `Location` can't be read back: the row
	 *  then shows only the track's name, and leaves the list once a read made
	 *  after the removal has no row matched to the track.
	 */
	path: string | null,
	/**  When the user removed it (or switched its file), UTC ISO-8601. */
	removedAt: string,
};

/**
 *  The value the user chose for one field: the track it comes from, and the
 *  text the screen showed (the merge is refused if it isn't the track's
 *  value any more).
 */
export type MergeChoice = {
	field: string,
	from: number,
	value: string,
};

/**  A field the merge asks about. */
export type MergeField = {
	/**  The rekordbox XML attribute name, e.g. `Rating`. */
	field: string,
	kind: ValueKind,
	/**  Every track of the item, the one that stays first. */
	values: FieldValue[],
	/**  The track whose value is chosen by default. */
	chosen: number,
};

/**  What a merge did. */
export type Merged = {
	operationId: number | null,
	/**  The track that stays. */
	kept: number,
	/**  The tracks merged into it. */
	merged: number[],
};

/**  The missing tracks that were last in one folder. */
export type MissingGroup = {
	/**
	 *  The last known folder, as Windows writes it. `None` for tracks whose
	 *  Location couldn't be decoded.
	 */
	folder: string | null,
	/**
	 *  Whether the folder exists now and is outside every music folder, so
	 *  adding it as a music folder (`add_music_folder`) makes sense.
	 */
	canAdd: boolean,
	/**
	 *  Every missing track in the group, in the order shown. Its length is
	 *  the group's count.
	 */
	trackIds: number[],
	/**
	 *  The first tracks of the group, in full; the rest come from
	 *  `missing_track_page`.
	 */
	tracks: MissingTrack[],
};

export type MissingList = {
	total: number,
	/**  By folder, in folder order; tracks with no known folder last. */
	groups: MissingGroup[],
};

/**  A rekordbox track with no file. */
export type MissingTrack = {
	/**  The row's id, for the app. Not rekordbox's TrackID. */
	id: number,
	title: string,
	artist: string,
	/**
	 *  Where rekordbox last had the file, as Windows writes it. `None` if
	 *  the Location couldn't be decoded.
	 */
	lastKnownPath: string | null,
};

/**  A music folder, as the frontend sees it. */
export type MusicFolder = {
	id: MusicFolderId,
	role: MusicFolderRole,
	/**  Whether the folder's watcher is on (1aC-6). */
	watch: boolean,
	/**
	 *  Where the folder is, e.g. `E:\DJ Music`: under the volume's mount
	 *  point now, or where it was last seen if the volume is offline.
	 */
	path: string,
	/**  Whether its volume is mounted right now. */
	online: boolean,
	/**  The volume's label, e.g. `GIG USB`. May be empty. */
	volumeLabel: string,
	/**  When it was added, UTC ISO-8601. */
	addedAt: string,
	/**
	 *  When a scan last walked the whole folder, UTC ISO-8601. `None` until
	 *  one has.
	 */
	walkedAt: string | null,
	/**
	 *  Folders inside it that the last walk couldn't list (1aB-14). `None`
	 *  until a walk has finished.
	 */
	unreadableFolders: number | null,
	/**
	 *  Audio files in it that the last walk couldn't look at, or whose
	 *  names can't be stored (1aB-14). `None` until a walk has finished.
	 */
	unreadableFiles: number | null,
	/**  Files in it that are online only (OneDrive placeholders, 1aB-8). */
	onlineOnlyFiles: number,
};

/**  A music folder's row id. */
export type MusicFolderId = number;

/**  What a music folder is for. Stored in `music_folder.role`. */
export type MusicFolderRole = 
/**  Scanned into All music (the default). */
"scan" | 
/**  Watched for new arrivals (Phase 2, ROADMAP 2.1). */
"inbox";

/**  A file, by name. */
export type NamedFile = {
	id: number,
	/**  The name without its folder, e.g. `a.mp3`. */
	name: string,
};

/**
 *  One reason a candidate ranks where it does, as data for the screen to
 *  word. Only the fields its `code` names are set.
 */
export type NextReason = {
	code: ReasonCode,
	/**  Counts for the candidate (a fitness of at least a half). */
	good: boolean,
	/**  Keys as Camelot (`8A`); the screen shows them in the user's notation. */
	from: string | null,
	to: string | null,
	delta: number | null,
	step: number | null,
	count: number | null,
	/**  The tags in common, for `TagsShared`. */
	tags: string[] | null,
};

/**  The best next tracks. */
export type NextReply = {
	results: NextResult[],
	/**  How many Library tracks were weighed. */
	considered: number,
	/**
	 *  Signals that count but could not be used, because the chosen track
	 *  has nothing to compare.
	 */
	ignored: Signal[],
	settings: NextSettings,
};

/**  One suggestion. */
export type NextResult = {
	/**  The track, as the track table shows it. */
	row: TableRow,
	/**  0 to 100. */
	score: number,
	/**  The top reasons, strongest first, for the screen to word. */
	reasons: NextReason[],
};

/**  The weights and the tolerance. */
export type NextSettings = {
	weights: NextWeights,
	tolerance: Tolerance,
};

/**  What Undo would do now. */
export type NextUndo = {
	/**  The operation Undo would take back; none when nothing is left. */
	operation: OperationInfo | null,
	/**
	 *  Why it would be refused, when that's known. `None` doesn't promise
	 *  the undo will work: a very large operation isn't tried ahead of time
	 *  (see [`TRIED_AHEAD_UP_TO`]).
	 */
	refusal: UndoRefusal | null,
};

/**  How much each signal counts, 0 (off) to [`MOST_WEIGHT`]. */
export type NextWeights = {
	key: number,
	bpm: number,
	energy: number,
	played: number,
	genre: number,
	tags: number,
};

/**  A Library track that has no genre. */
export type NoGenreTrack = {
	recordingId: number,
	title: string,
	artist: string,
};

/**  What S did. */
export type NotSame = {
	operationId: number | null,
	/**
	 *  The item is still in the queue: a split left the question between its
	 *  other tracks open. The screen then stays on it (foreman's answer,
	 *  2026-10-16); otherwise it goes on to the next item.
	 */
	itemStays: boolean,
};

/**
 *  Comparing a number. `Between` takes `value` and `to`, either way round;
 *  with no `to` it is `Is`.
 */
export type NumberOp = "is" | "isNot" | "atLeast" | "atMost" | "between";

/**  What the offer holds now. */
export type Offer = {
	/**  Tracks the add would put in the Library. */
	toAdd: number,
	/**  Tracks with a trusted match that are in the Library already. */
	alreadyInLibrary: number,
	/**  rekordbox entries with no file: waiting in Review's Missing list. */
	waitingInMissing: number,
	/**  rekordbox entries whose match is still probable. */
	waitingForConfirmation: number,
};

/**
 *  What the UI needs to name an operation, read from its `details`. Each
 *  is there only if the operation recorded it.
 */
export type OperationDetails = {
	/**  The crate's name (after a rename, the new one). */
	name: string | null,
	/**  A renamed crate's name before. */
	from: string | null,
	/**  How many tracks the operation added or removed. */
	tracks: number | null,
	/**
	 *  How many of the tracks an add to a crate put in the Library too
	 *  (1cB-23). Left out when the operation didn't record it.
	 */
	newToLibrary: number | null,
	/**  Whether an add to a crate made the crate as well (1cB-23). */
	newCrate: boolean | null,
};

/**  An operation, as undo reports it. */
export type OperationInfo = {
	/**
	 *  The operation's row id. Row ids cross IPC as plain numbers (see
	 *  `ipc.rs`).
	 */
	id: number,
	/**
	 *  What kind of action it was, e.g. `edit_fields`. The UI describes it
	 *  from the locale files.
	 */
	kind: string,
	details: OperationDetails,
};

/**
 *  A Library track whose linked file rekordbox doesn't have, while it
 *  already has another file of the same track: sending adds a second
 *  rekordbox entry.
 */
export type OtherFile = {
	track: TrackLabel,
	/**  The Library track's file, which the send adds. */
	libraryFile: string | null,
	/**  The file rekordbox already has. */
	rekordboxFile: string | null,
};

/**  Every Overview number. */
export type Overview = {
	/**  Library tracks. */
	tracks: number,
	/**  The Library's length: the sum of its linked files' durations. */
	totalLengthMs: number,
	/**  Library tracks in at least one crate or playlist. */
	inCrates: number,
	/**  Library tracks in no crate. */
	inNoCrate: number,
	/**  Library tracks rekordbox supplied a BPM or a key for. */
	analyzedByRekordbox: number,
	/**  Library tracks it didn't. */
	notAnalyzed: number,
	/**
	 *  Whether a rekordbox library was ever read. Before that every track
	 *  is "not analyzed", which says nothing.
	 */
	rekordboxRead: boolean,
	/**
	 *  Library tracks whose linked file has a current verdict that is not
	 *  `ok`. A file with no current verdict isn't counted.
	 */
	lowQuality: number,
	/**
	 *  When the Library was last sent, in milliseconds since the Unix
	 *  epoch; `None` if never.
	 */
	lastSentMs: number | null,
	/**  Tracks in All music: tracks with a file that isn't hidden. */
	allMusic: number,
	/**  Library tracks added in the last 7 days ([`THIS_WEEK`]). */
	addedThisWeek: number,
	/**  Operations made in the last 7 days ([`THIS_WEEK`]). */
	decisionsThisWeek: number,
	/**  Every genre, most tracks first, then by name. */
	genres: GenreCount[],
	/**  Library tracks with no genre. */
	noGenre: number,
	/**
	 *  Library tracks per energy level: entry 0 is energy 1 and entry 9 is
	 *  energy 10 ([`ENERGY_LEVELS`] entries), the energy a track shows.
	 */
	energy: number[],
	/**  Library tracks with no energy. */
	noEnergy: number,
	/**
	 *  Tracks in All music that are not Library tracks: what "Add to
	 *  Library" could still bring in.
	 */
	outsideLibrary: number,
	/**
	 *  Library tracks with no title, no artist or no genre, as the lists
	 *  show them ([`missing_tag_ids`]), counted from the flag the index job
	 *  keeps (`counting.index` says when it is behind).
	 */
	missingTags: number,
	/**
	 *  Library tracks whose linked file has tags and no embedded cover
	 *  ([`missing_art_sql`]), counted from the flag the index job keeps.
	 */
	missingArt: number,
	counting: Counting,
};

/**  One play of a session. */
export type Play = {
	id: number,
	/**  Its place in the session, from 0. */
	position: number,
	/**  The track it matched, if any. */
	recordingId: number | null,
	artist: string | null,
	title: string | null,
	path: string,
};

/**  A playlist, as the sidebar and the playlist screen list it. */
export type Playlist = {
	id: PlaylistId,
	name: string,
	origin: PlaylistOrigin,
	/**
	 *  For a copy of a rekordbox playlist, its path in rekordbox (folder
	 *  names down to the playlist), for display. `None` for the app's own.
	 */
	sourcePath: string[] | null,
	/**  How many entries it has, repeats counted. */
	trackCount: number,
};

/**  What adding, removing or moving entries did. */
export type PlaylistChanged = {
	/**  Entries added, removed or moved. */
	changed: number,
	/**  Entries asked about that aren't in the playlist, so were left alone. */
	skipped: number,
	/**  The operation this recorded; `None` when nothing changed. */
	operationId: number | null,
};

/**
 *  A rekordbox playlist to pick, with how many of its entries are tracks
 *  with a file or a last known path (streaming entries aren't counted).
 */
export type PlaylistChoice = {
	path: string[],
	tracks: number,
};

/**
 *  One entry's row id: a track's place in a playlist (a track that is in it
 *  twice has two).
 */
export type PlaylistEntryId = number;

/**  A playlist's row id. */
export type PlaylistId = number;

/**
 *  One entry of a playlist with the track's row as the track table shows
 *  it (energy, key, BPM and length included).
 */
export type PlaylistItem = {
	entryId: PlaylistEntryId,
	/**  From 0, dense. */
	position: number,
	row: TableRow,
};

/**  Where a playlist came from. */
export type PlaylistOrigin = 
/**  Made in the app (a conversion from a crate included). */
"app" | 
/**  Copied once from a rekordbox playlist ([`import`]). */
"rekordbox";

/**  A playlist and every entry, in order. */
export type PlaylistView = {
	playlist: Playlist,
	items: PlaylistItem[],
};

/**  The plays of a session, and whether "Add to a wishlist" is offered. */
export type PlaysReply = {
	plays: Play[],
	/**  Wishlists are on: the unmatched plays can go to one. */
	wishlistOffer: boolean,
};

/**  What a send would do, worked out without writing a file. */
export type Preflight = {
	/**  Names this preflight; the write must be given it back. */
	token: string,
	export: ExportRead,
	/**  Tracks rekordbox doesn't have yet. No dialog for these. */
	newTracks: number,
	/**  Tracks rekordbox already has: one Yes/No dialog each on import. */
	knownTracks: number,
	leftOut: LeftOut[],
	/**
	 *  Tracks rekordbox has whose file is missing: sent all the same, as
	 *  rekordbox's own entry, so the crates naming them stay whole.
	 */
	fileMissing: TrackLabel[],
	/**
	 *  Tracks rekordbox has that are sent with rekordbox's own `Location`
	 *  while no file is there: the app paired rekordbox's entry with a
	 *  file somewhere else (same name and length, say), and a known
	 *  track's `Location` is never changed by a send. rekordbox couldn't
	 *  find the file before the import and still won't after it. A track
	 *  in [`Preflight::file_missing`] is never here too. Looked up on disk
	 *  once, by the prepare step; the token doesn't cover it, so a file
	 *  that comes back before the go changes nothing about the go.
	 */
	noFileAtLocation: TrackLabel[],
	otherFile: OtherFile[],
	/**
	 *  New tracks sent without a `Kind`: their file is in a format
	 *  rekordbox isn't known to play (Ogg, Opus, WMA and the like), or in
	 *  one the app couldn't tell. They're sent all the same, exactly as
	 *  before; rekordbox may refuse them on import or fail to play them.
	 *  Read off the send itself, so it never changes whether a send may be
	 *  written.
	 */
	noKind: TrackLabel[],
	/**
	 *  Not empty: the send needs an explicit confirm
	 *  ([`Preflight::needs_confirm`] says when it's needed).
	 */
	losesEntries: LosesEntries[],
	/**
	 *  Fields of the tracks sent with an open conflict: they wait in Review
	 *  → Conflicts, and the send carries rekordbox's value for each until
	 *  the user decides ([`crate::conflicts::open_at_send`]).
	 */
	conflictsWaiting: number,
	/**
	 *  How many tracks rekordbox has get different stars from this send,
	 *  counted from this fresh read and merge. `None` while energy isn't
	 *  sent as the star rating ([`crate::energy_stars`]). The token covers it.
	 */
	starsChanged: number | null,
	/**
	 *  Tracks rekordbox has, sent with rekordbox's values from this export,
	 *  whose file changed after the export was saved: rekordbox writes a
	 *  DJ's edits into the file, so rekordbox may hold an edit this export
	 *  doesn't, and a Yes on import would overwrite it (1.10, "Second
	 *  channel"). A warning only: the user is asked to export again, and the
	 *  send goes all the same if they choose. A file tag is never taken as
	 *  rekordbox's value. Told by the file's modified time, as the last
	 *  scan recorded it or, looked up once by the prepare step, on disk now
	 *  (`preflight::changed_on_disk`); the token doesn't cover it, so a
	 *  change between the review and the go changes nothing about the go.
	 */
	changedAfterExport: TrackLabel[],
	/**  Set when the send can't go at all. */
	refusal: Refusal | null,
	/**
	 *  No track would be sent and there's no crate or playlist: the send
	 *  can't be started.
	 */
	nothingToSend: boolean,
	/**
	 *  Whether the user's go can start the write: the send isn't refused
	 *  and there's something to send.
	 */
	canSend: boolean,
	/**
	 *  The export was saved before the last send was recorded, so it can't
	 *  show anything that send put in rekordbox. Whether it did put
	 *  anything there only the user knows (the app can't see an import),
	 *  so the checklist asks: has a send been imported into rekordbox since
	 *  this export was saved? The go is taken only with the answer "no"
	 *  ([`SendFailure::ExportOlderThanLastSend`] otherwise). The answer is
	 *  for this one send: it's kept only in that send job's own row, and
	 *  no later send reads it.
	 */
	exportOlderThanLastSend: boolean,
	/**
	 *  Whether the go needs the explicit confirm: a crate or playlist
	 *  loses entries, or the read couldn't store some of rekordbox's
	 *  tracks (a Library track on such a track's file would be sent as
	 *  new, and a Yes in rekordbox would overwrite that entry).
	 */
	needsConfirm: boolean,
};

/**  Why a file can't be previewed. The player shows a line for each. */
export type PreviewRefusal = 
/**  No such file, or not in a music folder the app knows. */
"unknown_file" | 
/**  The last scan didn't find it, or it isn't there now. */
"missing" | 
/**  Its drive isn't connected. */
"drive_not_connected" | 
/**
 *  A OneDrive file that isn't on this PC. Never opened: reading it
 *  would download it.
 */
"online_only" | 
/**  The OS wouldn't read it (locked, no access, an I/O error). */
"unreadable" | 
/**  Not a format the player can play, or damaged beyond decoding. */
"not_decodable";

/**  What asking to add a track to the Library came to. */
export type PromoteOutcome = 
/**  The track is in the Library now (or was already: `added` says). */
{
	outcome: "done",
} & Promoted | 
/**
 *  Nothing was added or recorded. Ask again with the matching
 *  confirmation to add it anyway.
 */
{ outcome: "needsConfirmation"; warning: AddWarning };

/**  What adding a track to the Library did. */
export type Promoted = {
	libraryTrack: LibraryTrack,
	/**  False when the track was already in the Library: nothing changed. */
	added: boolean,
};

/**  The last read that failed. The snapshot is unchanged by it. */
export type ReadFailure = {
	path: string,
	reason: FailureReason,
	/**  When it failed (UTC, ISO 8601). */
	at: string,
};

/**  Where a read came from. */
export type ReadSource = 
/**  rekordbox's XML export. */
"xml" | 
/**  rekordbox's own library database (optional, ROADMAP 2.7). */
"database";

/**  One reason for a suggestion: an i18n key, its parameters and its source. */
export type Reason = {
	/**  An i18n key with its namespace, e.g. `crates:reason.sameKey`. */
	key: string,
	params: { [key in string]: ReasonParam },
	source: ReasonSource,
};

/**  Which reason, as the key the screen words it by: `next:reason.<code>`. */
export type ReasonCode = 
/**  The same key (`from`). */
"keySame" | 
/**  One number up or down, the same letter (`from`, `to`). */
"keyAdjacent" | 
/**  The same number, the other letter: relative major or minor. */
"keyRelative" | 
/**  Two numbers up or down, the same letter. Counted only when wide. */
"keyTwoSteps" | 
/**  One number up or down, the other letter. Counted only when wide. */
"keyDiagonal" | 
/**  Any other key. */
"keyFar" | 
/**  The candidate has no key. */
"keyNone" | 
/**  `delta` BPM above or below, read as it is. */
"bpm" | 
/**  `delta` BPM, the candidate at half the chosen track's tempo. */
"bpmHalf" | 
/**  `delta` BPM, the candidate at double the chosen track's tempo. */
"bpmDouble" | 
/**  The candidate has no BPM. */
"bpmNone" | 
/**
 *  The shown energy is `step` above (positive) or below the chosen
 *  track's.
 */
"energyStep" | 
/**  The candidate has no energy, which is why it is last. */
"energyNone" | 
/**  Played right after the chosen track `count` times. */
"playedAfter" | 
/**  The same genre (`from`). */
"genreSame" | 
/**
 *  A genre next to the chosen track's: a sibling, parent or child
 *  (`from`, `to`).
 */
"genreRelated" | 
/**  `tags` in common (`count` of them). */
"tagsShared";

/**
 *  A value filled into a reason's text, e.g. `bpm` = 2 or `tag` = "Peak Time".
 * 
 *  Text parameters are data (a tag name, a title), never prose: the words
 *  around them live in the locale file. Numbers stay numbers so the frontend
 *  formats them for the user's language.
 */
export type ReasonParam = string | number | null;

/**  Where a reason comes from. */
export type ReasonSource = 
/**  A fact from the Library, rekordbox or the files: a key, a BPM, a tag. */
"fact" | 
/**
 *  The audio model's opinion (3.8). Labeled as such in the UI, optional,
 *  and never the only reason.
 */
"audioModel";

/**  A refused send, explained. */
export type Refusal = {
	reason: RefusalReason,
	/**
	 *  Where in the tree the problem is, from `Crates` or `Playlists`
	 *  down; empty when the reason isn't about the tree.
	 */
	path: string[],
};

/**  Why the whole send is refused. */
export type RefusalReason = 
/**
 *  The export just read doesn't hold every track it says it does, so
 *  some of rekordbox's values would come from an older read.
 */
"incompleteExport" | 
/**
 *  Two crates, playlists or folders in one folder share a name (or
 *  names rekordbox may treat as one): one would replace the other.
 */
"sameName" | 
/**  A crate, playlist or folder has no name. */
"noName" | 
/**  A name holds a character XML can't carry. */
"unsendableName" | 
/**  Folders nest too deep. */
"tooDeep" | 
/**  The file couldn't be made (a bug; nothing is written). */
"internal";

/**  What the Settings row shows. With the feature off, nothing. */
export type RekordboxDatabase = {
	/**  Whether a key was typed in this run of the app. */
	keySet: boolean,
	/**
	 *  How many reads have failed in this run: changes exactly when one
	 *  does, so a read has ended when this or `last_read` changes.
	 */
	failures: number,
	/**  Why the newest read failed, until one works. */
	failure: DbFailure | null,
	/**  The newest read, when it was of the database. */
	lastRead: LastRead | null,
	/**  rekordbox's usual folder, where the picker opens, if it's there. */
	usualFolder: string | null,
};

/**  A playlist of the newest rekordbox read, to copy. */
export type RekordboxPlaylist = {
	/**  Folder names from below ROOT down to the playlist. */
	path: string[],
	/**
	 *  Its entries, every one (repeats, and tracks outside the Library,
	 *  included).
	 */
	entries: number,
};

/**  Whether rekordbox knows a file. */
export type RekordboxUse = "unknown" | "probable" | "trusted";

/**
 *  What a "Confirm relink" item offers to decide: the file its entry is
 *  probably matched to.
 */
export type RelinkOffer = {
	/**  The matched file. */
	fileId: number,
	/**
	 *  The user confirmed this very match before, and the file holds other
	 *  audio now: it is asked again.
	 */
	confirmedBefore: boolean,
};

/**  What a relocation did, for the screen to say. */
export type Relocated = {
	id: MusicFolderId,
	/**  How many of the checked files were found at the new place. */
	found: number,
	/**  How many known files were looked for (at most [`SAMPLE_CAP`]). */
	checked: number,
	/**  The folder's new place as a person reads it. */
	path: string,
};

/**  Why a track is to be removed in rekordbox. */
export type RemovalReason = 
/**  The user removed the track from the Library. */
"removed" | 
/**
 *  The track is still in the Library, linked to another file since the
 *  user switched it in Review: this is the entry of the file that is
 *  gone, which the track is no longer sent as (`replaced_entry`).
 */
"replaced" | 
/**
 *  The Library track it was sent as was merged into another Library
 *  track that is the same recording (Review, 1bE-9): this entry is the
 *  one of the track that left (`replaced_entry`, reason `merge`).
 */
"merged";

/**  The node a spelling resolved to, and why. */
export type Resolution = {
	node: number,
	rule: Rule,
};

/**  The comparison for one item: its files, the suggested one first. */
export type ReviewComparison = {
	id: ReviewItemId,
	kind: ReviewKind,
	group: ReviewGroup,
	tracks: ReviewTrackName[],
	/**
	 *  Why the item is in the queue, from the grouping's own reasons (a
	 *  version doubt, a held set): at most three, the deciding one first.
	 */
	doubt: Reason[],
	/**
	 *  A possible version mix-up whose own reasons, the ones in `doubt`,
	 *  say the names give different versions (other cuts or reworks,
	 *  [`split::NAMES_SAY_VERSIONS`]): its filled button is "Not the same"
	 *  or "Split off", not "Same track" (DOGFOOD B-4). `false` for every
	 *  other item.
	 */
	namesSayVersions: boolean,
	/**
	 *  The file the app suggests (`what` is its id) and why. `None` when
	 *  there is nothing to suggest (a quality problem with no better copy).
	 */
	suggestion: Suggestion<number> | null,
	/**  The first [`MAX_FILES`] files, the suggested one first. */
	rows: ReviewFileRow[],
	moreFiles: number,
	/**
	 *  The switch a "Linked file gone, copy found" item offers: to which
	 *  file, and what it means in rekordbox (or why it can't be made).
	 *  `None` for every other kind.
	 */
	switch: SwitchOffer | null,
	/**
	 *  The switch to every copy of a "Linked file gone, copy found" item that
	 *  is on disk (the suggested one too), for the number keys: a digit
	 *  switches to the copy in that row. Empty for every other kind.
	 */
	copies: SwitchOffer[],
	/**
	 *  The match a "Confirm relink" item asks about. `None` for every other
	 *  kind.
	 */
	relink: RelinkOffer | null,
	/**
	 *  The Library tracks a "Same track twice" item offers to keep both of
	 *  or merge (1bE-9). `None` for every other kind.
	 */
	sameRecording: SameRecordingOffer | null,
};

/**  How many items wait, by group. */
export type ReviewCounts = {
	needsCloserLook: number,
	clearBestFile: number,
	qualityProblems: number,
	/**  Open conflicts (1cB-1): one each, however the screen groups them. */
	conflicts: number,
	/**
	 *  How many need a decision in all: the four above added up. What the
	 *  Overview and the sidebar can show.
	 */
	total: number,
};

/**  One row of a comparison: a file, with the same columns for every file. */
export type ReviewFileRow = {
	fileId: number | null,
	source: RowSource,
	/**  The track the file is in; `None` for rekordbox's entry. */
	recordingId: number | null,
	name: string,
	path: string | null,
	/**  The last scan found it on disk (a file on an unplugged drive is). */
	onDisk: boolean,
	driveConnected: boolean,
	/**  The Library track plays this file. */
	linked: boolean,
	/**  The format sniffed from the bytes, e.g. `mp3`, `flac`. */
	format: string | null,
	/**  `None`: not checked. */
	verdict: Verdict | null,
	cutoffHz: number | null,
	durationMs: number | null,
	tagsFilled: number,
	tagsTotal: number,
	hasArt: boolean,
	rekordbox: RekordboxUse,
	bitrateKbps: number | null,
	sampleRateHz: number | null,
	addedAt: string | null,
};

/**  The queue's groups, in the order they are shown. */
export type ReviewGroup = "needsCloserLook" | "clearBestFile" | "qualityProblems";

/**  One line of the queue. */
export type ReviewItem = {
	id: ReviewItemId,
	kind: ReviewKind,
	/**  The first [`MAX_NAMES`] tracks. */
	tracks: ReviewTrackName[],
	/**  How many more tracks the item has. */
	moreTracks: number,
};

/**
 *  Which item. A pair item names its two tracks (`a` < `b`); a held or
 *  same-recording set names its lowest track (`b` is `None`); a relink item
 *  names the rekordbox entry; the others name the Library track's track.
 */
export type ReviewItemId = {
	kind: ReviewKind,
	a: number,
	b: number | null,
};

/**  What kind of decision an item asks for. */
export type ReviewKind = "versionDoubt" | "heldSet" | "sameRecording" | "relink" | "clearBestFile" | "qualityProblem" | "betterFile";

/**  A page of one group. */
export type ReviewPage = {
	group: ReviewGroup,
	/**  How many items the group has in all. */
	total: number,
	items: ReviewItem[],
};

/**  A track named for the queue. */
export type ReviewTrackName = {
	/**  `None` for rekordbox's own entry (a relink item). */
	recordingId: number | null,
	title: string | null,
	artist: string | null,
};

/**  What the Fit column shows for a row. */
export type RowFit = {
	/**  0 to 3. */
	dots: number,
	/**
	 *  Why; `None` for the selected track itself, which has no fit to
	 *  itself.
	 */
	reason: FitReason | null,
};

/**  What a comparison row stands for. */
export type RowSource = "file" | 
/**  rekordbox's own entry (a relink item): the file it names is gone. */
"rekordboxEntry";

/**  Which rule mapped a spelling to a node. Tried in this order. */
export type Rule = 
/**  The spelling is the node's name, letter for letter. */
"exact" | 
/**  The same once case and accents are folded. */
"folded" | 
/**  `Parent (Sub)`: a node `Sub` that sits under a node `Parent`. */
"parentSub" | 
/**  An alias the user made. */
"alias";

/**
 *  What a "Same track twice" item offers: its Library tracks, the one the
 *  app suggests keeping first.
 */
export type SameRecordingOffer = {
	tracks: SameRecordingTrack[],
	/**  The track the app suggests keeping in a merge ([`suggest_keep`]). */
	keep: number | null,
	/**
	 *  Two of the tracks are linked as versions: versions never merge, so
	 *  the item offers "Keep both" only, and says why.
	 */
	linkedVersions: boolean,
};

/**  One Library track of a "Same track twice" item. */
export type SameRecordingTrack = {
	recordingId: number,
	libraryTrackId: LibraryTrackId,
	linkedFileId: number | null,
	/**  `None`: rekordbox doesn't know the track (it is sent as a new one). */
	rekordbox: EntryFacts | null,
	/**  How many crates hold it. */
	crates: number,
};

/**  Where a saved report is. */
export type SavedReport = {
	path: string,
};

/**  Why a step of the send stopped. Nothing was sent. */
export type SendFailure = 
/**  The export couldn't be read; the rekordbox source says why. */
"readFailed" | 
/**  The step was cancelled. */
"cancelled" | 
/**  There's no preflight to send, or not the one named. */
"noPreflight" | 
/**  The export changed, or was read again, after the preflight. */
"exportChanged" | 
/**
 *  The Library changed after the preflight: the send would differ
 *  from what was reviewed.
 */
"libraryChanged" | 
/**  The preflight says the send is refused, or has nothing to send. */
"notSendable" | 
/**  The send needs the explicit confirm and it wasn't given. */
"notConfirmed" | 
/**
 *  The export is older than the last send
 *  ([`Preflight::export_older_than_last_send`]) and the user didn't
 *  answer that no send was imported into rekordbox since: they said
 *  one was, or said nothing. They export again.
 */
"exportOlderThanLastSend" | 
/**
 *  The file couldn't be written. The file from the last send is as it
 *  was.
 */
"cantWrite" | 
/**
 *  The file was written but the send couldn't be recorded. The file
 *  from the last send is put back when there was one and it can be;
 *  otherwise the new file stays, unrecorded, until the next send
 *  replaces it.
 */
"cantRecord" | 
/**  The database failed, or a bug. */
"internal";

/**  Everything the checklist shows. */
export type SendState = {
	/**  Goes up each time a step ends, however it ends. */
	revision: number,
	/**  The one file a send writes, replaced every time. */
	filePath: string,
	/**  The export that will be read, if one is chosen. */
	exportPath: string | null,
	/**  The preflight waiting for the go. */
	preflight: Preflight | null,
	/**  The step that ended last, in this run of the app. */
	step: SendStep | null,
	/**  What the step under way is doing now; `None` between steps. */
	workingOn: SendWork | null,
	/**  Why the last step stopped, until the next step starts. */
	failure: SendFailure | null,
	/**  The last send of this run of the app, until the next read starts. */
	sent: Sent | null,
};

/**  One of the send's two steps. */
export type SendStep = "prepare" | "write";

/**
 *  What a step is doing now, for the checklist to name. A job only reports
 *  how far it has got, so this says what the number is about.
 */
export type SendWork = 
/**  Reading rekordbox's export. */
"reading" | 
/**  Matching its tracks to files. */
"matching" | 
/**  Merging the two sides (1.10). */
"merging" | 
/**  Building the send and reading it back. */
"building" | 
/**  Looking at the files on disk. */
"lookingAtFiles" | 
/**  Writing the send's file. */
"writing" | 
/**  Recording the send. */
"recording";

/**  A send that went through. */
export type Sent = {
	/**  When it was recorded (UTC, ISO 8601). */
	at: string,
	newTracks: number,
	/**  How many Yes/No dialogs to expect in rekordbox. */
	knownTracks: number,
};

/**  A session, with its counts. */
export type SessionSummary = {
	id: number,
	/**  `m3u8` or `stick`. */
	source: string,
	name: string,
	/**  `YYYY-MM-DD`. */
	playedOn: string,
	importedAt: string,
	plays: number,
	matched: number,
};

/**  The settled conflict, as the screen needs to know it. */
export type Settled = {
	libraryTrack: LibraryTrackId,
	field: string,
	status: Status,
	/**  The value that is now the field's. */
	value: string,
};

/**  What "Show again" did. */
export type ShownAgain = {
	/**
	 *  The operation to offer Undo for. `None` if the file wasn't hidden by
	 *  the user or cleared from the Inbox (shown already, or gone): nothing
	 *  changed.
	 */
	operationId: number | null,
};

/**  What a bulk settling keeps. */
export type Side = "app" | "rekordbox";

/**  The signals that carry a weight. */
export type Signal = "key" | "bpm" | "energy" | "played" | "genre" | "tags";

/**  Why "Accept all" left an item as it is. */
export type SkipReason = "linkedOnDisk" | "notInTrack" | "targetGone" | "targetLinked" | "entryOfAnotherTrack" | 
/**
 *  The switch would arrive in rekordbox as a new track without the old
 *  cues: not a clear case ([`accept_all_covers`]).
 */
"newTrack" | 
/**  The switch would make the track another of rekordbox's entries. */
"otherEntry" | 
/**
 *  The item isn't in the queue any more, or suggests another copy than
 *  the one the screen showed.
 */
"itemGone";

/**  An item "Add all" left as it was, and why. */
export type Skipped = {
	itemId: number,
	reason: InboxRefusal,
};

/**  An item "Accept all" left in the queue. */
export type SkippedItem = {
	recordingId: number,
	reason: SkipReason,
};

/**
 *  A smart crate's rule: its conditions, all of them or any of them. No
 *  condition matches no track (the crate holds its always-include list only).
 */
export type SmartRule = {
	combine: Combine,
	conditions: Condition[],
};

/**  What a read did to the snapshot. */
export type SnapshotSummary = {
	/**  Tracks stored from this read, streaming ones included. */
	tracks: number,
	/**  Of those, streaming entries (no file). */
	streaming: number,
	/**  Tracks kept from earlier reads because this export is incomplete. */
	kept: number,
	/**  Tracks in the export that couldn't be stored. */
	notStored: number,
	/**  Whether the export held every track it said it did. */
	complete: boolean,
};

/**  A column the table can be sorted by. */
export type SortColumn = "title" | "artist" | "bpm" | "key" | "time" | "genre" | "rating" | "energy" | "dateAdded" | "file" | "folder";

/**  A value and the place it comes from. */
export type SourcedValue = {
	value: string,
	origin: ValueOrigin,
	/**  The file the value is the tag of; `None` for rekordbox's. */
	file: NamedFile | null,
};

/**
 *  A genre spelling as tracks have it, and where it goes. `resolution` is
 *  `None` for an unmapped spelling.
 */
export type Spelling = {
	spelling: string,
	tracks: number,
	resolution: Resolution | null,
};

/**  Whether a stale entry is a folder or a playlist. */
export type StaleKind = "folder" | "playlist";

/**  A playlist or folder in rekordbox that the app doesn't have. */
export type StalePlaylist = {
	/**  Folder names down to it, starting with `Crates` or `Playlists`. */
	path: string[],
	kind: StaleKind,
	/**  For a folder, how many playlists are in it (at any depth). */
	playlistsInside: number,
	/**
	 *  A folder with nothing in it at all (not even a subfolder). A folder
	 *  holding only subfolders has no playlists but isn't empty.
	 */
	empty: boolean,
};

/**  Where a conflict stands. Stored in `conflict.status`. */
export type Status = "open" | 
/**  Settled: the app's value was kept. */
"keptApp" | 
/**  Settled: rekordbox's value was kept. */
"keptRekordbox" | 
/**  Settled with a value given by hand (`resolved_value`). */
"edited";

/**  What a stick import came to. */
export type StickImport = 
/**  Done as one operation (`None` when every list was already imported). */
{ outcome: "done"; operationId: number | null; 
/**  The new sessions. */
sessions: number[]; 
/**
 *  Plays imported, and how many of them matched a track by the
 *  same audio.
 */
plays: number; matched: number; 
/**  Plays left unmatched because their audio is several tracks'. */
ambiguous: number; 
/**
 *  Plays left unmatched because their file on the stick couldn't be
 *  read (missing, too big, unreadable).
 */
unreadable: number; 
/**  Lists left out because they are already a session. */
alreadyImported: number; 
/**  Parts of the stick's database that couldn't be read. */
skipped: number } | { outcome: "refused"; reason: StickRefusal };

/**  A history list found on the stick. */
export type StickList = {
	id: number,
	name: string,
	plays: number,
};

/**  What reading a stick found. */
export type StickListing = { outcome: "listed"; lists: StickList[]; 
/**  Parts of the stick's database that couldn't be read. */
skipped: number } | { outcome: "refused"; reason: StickRefusal };

/**  Why a stick couldn't be read, or nothing was imported. */
export type StickRefusal = 
/**  The folder has no `PIONEER\rekordbox\export.pdb`. */
"noExport" | 
/**  It's there but couldn't be read or copied. */
"unreadable" | 
/**  It's over [`devicesql::MAX_BYTES`]. */
"tooBig" | 
/**  It isn't a rekordbox export database. */
"notAnExport" | 
/**  None of the lists asked for is on the stick with plays. */
"nothingChosen" | 
/**  Not a day of the calendar as `YYYY-MM-DD`. */
"badDate";

/**
 *  Something the app suggests (`what`), with the reasons it's suggested.
 * 
 *  Always has at least one reason, and at least one that isn't the audio
 *  model's. See the module docs.
 */
export type Suggestion<T> = {
	what: T,
	reasons: Reason[],
};

/**
 *  What switching a Library track's linked file means in rekordbox, by what
 *  the track is sent as before and after ([`sent_as`]).
 */
export type SwitchEffect = 
/**
 *  rekordbox doesn't know the track: it is sent as no entry today.
 *  Nothing of rekordbox's changes.
 */
"notInRekordbox" | 
/**
 *  rekordbox's entry stays the track's: relink trusts it on the copy
 *  (or the user confirmed it). rekordbox keeps the track and its cues,
 *  and shows the file as missing until it is relocated there.
 */
"keepsEntry" | 
/**
 *  The track is sent as rekordbox's entry today and as a new track on
 *  the copy: rekordbox sees a new track without the old cues, and the
 *  old entry goes on the list of tracks to remove in rekordbox.
 */
"newTrack" | 
/**
 *  The track is sent as one entry today, and on the copy as another
 *  entry rekordbox already holds for that file. The old entry goes on
 *  the list of tracks to remove in rekordbox.
 */
"otherEntry";

/**  The switch a "Linked file gone, copy found" item offers. */
export type SwitchOffer = {
	/**  The copy to switch to: the item's suggested file. */
	fileId: number,
	/**  What the switch means in rekordbox; `None` when it is refused. */
	effect: SwitchEffect | null,
	/**  Why the switch can't be made now, if it can't. */
	refusal: SwitchRefusal | null,
};

/**  Why a linked file can't be switched. Nothing was changed. */
export type SwitchRefusal = 
/**  The linked file is on disk after all. */
"linkedOnDisk" | 
/**  The file to switch to isn't a file of the track. */
"notInTrack" | 
/**  The file to switch to is gone from disk itself. */
"targetGone" | 
/**  Another Library track is linked to the file to switch to. */
"targetLinked" | 
/**
 *  A rekordbox entry matched to the file to switch to is the entry
 *  another Library track is sent as today: that track would lose it.
 */
"entryOfAnotherTrack";

/**  What a switch did. */
export type Switched = {
	operationId: number | null,
	track: SwitchedTrack,
};

/**  One track "Accept all" switched, as the switch returned it. */
export type SwitchedRef = {
	recordingId: number,
	fromFileId: number,
	toFileId: number,
};

/**  One switched Library track. */
export type SwitchedTrack = {
	recordingId: number,
	libraryTrackId: LibraryTrackId,
	/**  The linked file before: gone from disk. */
	fromFileId: number,
	/**  The linked file now. */
	toFileId: number,
	effect: SwitchEffect,
};

/**  A switched track with its name and the names of its old and new file. */
export type SwitchedView = {
	recordingId: number,
	track: ReviewTrackName,
	fromName: string,
	toName: string,
};

/**  The columns a screen shows, as the user left them. */
export type TableColumns = {
	/**  The ids of the columns shown, in order. */
	shown: string[],
	/**
	 *  The ids of every column the app had when this was saved. A column
	 *  added by a later version isn't in it, so it can be told from one the
	 *  user chose to hide: it appears only if it is a default column.
	 */
	known: string[],
	/**
	 *  The widths the user dragged columns to (1cB-21), in pixels, by column
	 *  id. A column with no entry has its default width.
	 */
	widths: { [key in string]: number },
};

/**  One filter chip. */
export type TableFilter = 
/**
 *  The file is not on disk: a Library track marked missing by the scan,
 *  or a track whose file is gone. (A file on an unplugged drive counts
 *  as on disk, as everywhere.)
 */
{ kind: "missing" } | 
/**
 *  rekordbox has the track: one of its files is the trusted match of a
 *  rekordbox entry.
 */
{ kind: "inRekordbox" } | 
/**  rekordbox doesn't have the track. */
{ kind: "notInRekordbox" } | 
/**  The file is in this format (`file.sniffed_format`, e.g. `flac`). */
{ kind: "format"; format: string } | 
/**  The track is one of Review's "Quality problems" (see the module doc). */
{ kind: "qualityProblem" } | 
/**  The track is in at least one crate. */
{ kind: "inCrate" } | 
/**  The track is in no crate. */
{ kind: "inNoCrate" } | 
/**  The track is in the Library. */
{ kind: "inLibrary" } | 
/**  The track is not in the Library. */
{ kind: "notInLibrary" } | 
/**
 *  The track's linked file has a current quality verdict that flags it
 *  (low bitrate, a suspected transcode, cut off or broken): the Overview's
 *  "tracks made from low-quality files" (`track_row` flag
 *  [`flag::LOW_QUALITY`]). Not the same as
 *  [`TableFilter::QualityProblem`], which is Review's group and leaves
 *  out a track with a better copy or a "Keep anyway".
 */
{ kind: "lowQuality" } | 
/**
 *  rekordbox supplied a BPM or a key for the track (the Overview's
 *  "analyzed").
 */
{ kind: "analyzedByRekordbox" } | 
/**  rekordbox didn't: a Library track with no `analysis` row from it. */
{ kind: "notAnalyzedByRekordbox" } | 
/**
 *  The energy the Library track shows is this level, 1 to 10 (the
 *  Overview's energy bars; `track_row` bits [`flag::ENERGY`]).
 */
{ kind: "energy"; level: number } | 
/**  No source gives the Library track an energy. */
{ kind: "noEnergy" } | 
/**
 *  The Library track has no title, no artist or no genre (the
 *  Overview's "tracks with missing tags"; `track_row` flag
 *  [`flag::MISSING_TAGS`]).
 */
{ kind: "missingTags" } | 
/**
 *  The Library track's linked file has tags and no embedded cover (the
 *  Overview's "tracks with missing art"; `track_row` flag
 *  [`flag::MISSING_ART`]).
 */
{ kind: "missingArt" } | 
/**
 *  The Library track's genre is this one, however it is capitalized (the
 *  Overview's genre bars; `track_row.genre_group`). Free text: it is
 *  bound as a parameter. A name that is blank, or that no track has,
 *  lists nothing.
 */
{ kind: "genre"; name: string } | 
/**
 *  The track has this tag (`tag_applied`). The tag's id is bound as a
 *  parameter. A tag that doesn't exist lists nothing.
 */
{ kind: "tag"; id: number };

/**  A window of rows. */
export type TablePage = {
	/**  How many rows the query has in all; only when asked for. */
	total: number | null,
	offset: number,
	rows: TableRow[],
	/**
	 *  The index job hasn't caught up with some change: a track may be
	 *  missing from the rows or out of place.
	 */
	behind: boolean,
};

/**
 *  Where one track is in a query's rows (1cA-5): the same source, search,
 *  filters and sort as a [`TableQuery`], and the track to find.
 */
export type TablePositionQuery = {
	source: TableSource,
	search: string | null,
	filters: TableFilter[],
	sort: TableSort | null,
	/**  The track to find (`TableRow::recording_id`). */
	recordingId: number,
};

/**  What the table is asked for. */
export type TableQuery = {
	source: TableSource,
	/**  Search text (`search::match_expression`); blank filters nothing. */
	search: string | null,
	filters: TableFilter[],
	/**  `None` is the source's own order. */
	sort: TableSort | null,
	/**  The first row of the window, counting from 0. */
	offset: number,
	/**  How many rows, at most [`MAX_WINDOW`]. */
	limit: number,
	/**
	 *  Also count the rows: the count costs about as much as a window, so
	 *  the first window asks for it and the others don't.
	 */
	withTotal: boolean,
};

/**  A row of the table. */
export type TableRow = {
	/**  The track's id, as "Add to Library" takes it. */
	recordingId: number,
	/**  Its Library track, if it is in the Library. */
	libraryTrackId: LibraryTrackId | null,
	/**
	 *  The title shown: rekordbox's for a Library track it knows, else the
	 *  file's tag, else `None` (the file's name stands in for it).
	 */
	title: string | null,
	artist: string | null,
	bpm: number | null,
	/**
	 *  The key as Camelot (`8A`); the screen shows it in the user's
	 *  notation.
	 */
	key: string | null,
	/**
	 *  The BPM shown is the app's own estimate (ROADMAP 3.7): no other source
	 *  has one. rekordbox's value replaces it after analysis.
	 */
	bpmEstimated: boolean,
	/**
	 *  The key shown is the app's own estimate (only while the test switch is
	 *  on).
	 */
	keyEstimated: boolean,
	/**  The length in milliseconds. */
	timeMs: number | null,
	genre: string | null,
	/**  Stars, 0 to 5, for a Library track rekordbox knows. */
	rating: number | null,
	/**
	 *  When it joined the Library, else when the scan first found it (UTC
	 *  ISO-8601).
	 */
	addedAt: string | null,
	/**
	 *  The file the row plays: the Library track's linked file, else the
	 *  file adding the track to the Library would link.
	 */
	file: LinkedFile | null,
	inLibrary: boolean,
	/**
	 *  One of its files is the probable match of a rekordbox track and the
	 *  match can't be confirmed yet, so it can't be added to the Library.
	 */
	matchNotConfirmed: boolean,
	/**  Why the linked file's location is fragile (Library tracks only). */
	fragile: FragileReason | null,
	/**  The linked file is gone (Library tracks only). */
	sourceMissing: boolean,
	/**  How many conflicts with rekordbox are still open for it. */
	openConflicts: number,
	betterFile: BetterFile | null,
	/**
	 *  How well the track follows the selected one, with the reason; only in
	 *  a [`TableSource::CrateByFit`] table.
	 */
	fit: RowFit | null,
	/**
	 *  The energy the track shows, 1 to 10: the Overview's answer
	 *  ([`crate::overview::shown_energy!`]), read from the same `analysis`
	 *  row as [`TableRow::energy_source`], so the two can't disagree.
	 */
	energy: number | null,
	/**  Whose word the shown energy is. `None` with no energy. */
	energySource: EnergySource | null,
	/**
	 *  The playlist entry the row is; only in a [`TableSource::Playlist`]
	 *  table, where a track in the playlist twice has two rows with two
	 *  entries (what moving and removing take).
	 */
	entryId: PlaylistEntryId | null,
};

/**
 *  The screens that show the track table. A crate is one screen: every crate
 *  shows the same columns, and so does every playlist.
 */
export type TableScreen = "library" | "allMusic" | "crate" | "playlist";

/**  The order the table is sorted in. */
export type TableSort = {
	column: SortColumn,
	descending: boolean,
};

/**  Which tracks the table lists. */
export type TableSource = 
/**  The Library tracks. */
{ kind: "library" } | 
/**  Every track that has a file. */
{ kind: "allMusic" } | 
/**  The Library tracks in one crate, in the order they were added. */
{ kind: "crate"; id: CrateId } | 
/**
 *  The Library tracks in one crate, sorted by how well they follow the
 *  track `after` (a `recording` id; 1cB-16): that track first, then the
 *  rest, best fit first. A sort is ignored: this source has its own order
 *  ([`crate::crates::fit`]), and its rows carry a `fit`.
 */
{ kind: "crateByFit"; id: CrateId; after: number } | 
/**
 *  A smart crate's tracks (3.3): the Library tracks its rule matches,
 *  with its always-include list and without its never-include list
 *  ([`crate::crates::smart::membership`]), in the Library list's order.
 *  `rule`, when given, stands in for the stored one: the rule builder's
 *  draft, for its live count. With no `id`, the draft's own tracks.
 */
{ kind: "smart"; id: CrateId | null; rule: SmartRule | null } | 
/**
 *  The Library tracks in one playlist, in the playlist's order, a track
 *  that is in it twice twice (3C-P1a). Each row carries its entry
 *  ([`TableRow::entry_id`]). A sort orders by a column and keeps the
 *  playlist's order for ties.
 */
{ kind: "playlist"; id: PlaylistId } | 
/**
 *  One playlist's tracks sorted by how well they follow the track `after`
 *  (a `recording` id; 4B-FU): that track first (every entry of it, if it
 *  is in twice), then the rest, best fit first. A sort is ignored, rows
 *  carry a `fit` and their entry, and the playlist itself is not changed.
 */
{ kind: "playlistByFit"; id: PlaylistId; after: number };

/**  A tag, as the vocabulary panel lists it. */
export type Tag = {
	id: TagId,
	groupId: TagGroupId,
	name: string,
	colour: string | null,
	/**  The rekordbox My Tag it was copied from, as rekordbox spells it. */
	rekordboxName: string | null,
	/**
	 *  The last import didn't find that My Tag in rekordbox any more. The
	 *  tag stays; the app never deletes one by itself.
	 */
	goneFromRekordbox: boolean,
	/**  How many tracks have it. */
	trackCount: number,
};

/**  A tag field the panel lists, in the order it lists them. */
export type TagField = "title" | "artist" | "album" | "genre" | "composer" | "remixer" | "label" | "year" | "comment";

/**  A group and its tags. */
export type TagGroup = {
	id: TagGroupId,
	name: string,
	colour: string | null,
	tags: Tag[],
};

/**  A tag group's row id. */
export type TagGroupId = number;

/**  A tag's row id. */
export type TagId = number;

/**  Comparing tags: the track has one, or it doesn't. */
export type TagOp = "has" | "hasNot";

/**  What the Details panel lists for one track. */
export type TagSources = {
	/**
	 *  The track is a Library track rekordbox knows: its values are
	 *  rekordbox's.
	 */
	inRekordbox: boolean,
	/**  The fields that have a value somewhere, in the panel's order. */
	fields: FieldSources[],
	/**
	 *  The `rekordbox_track` row (`entry_id` of `review_withdraw_relink`)
	 *  whose match to the track's linked file the user confirmed, if there
	 *  is one to withdraw.
	 */
	confirmedEntry: number | null,
};

/**  What applying a tag to tracks, or removing it, did. */
export type TagsChanged = {
	/**  How many tracks gained or lost the tag. */
	changed: number,
	/**
	 *  How many were left alone: they had it already (applying), didn't have
	 *  it (removing), or no longer exist.
	 */
	skipped: number,
	/**  The operation this recorded; `None` when nothing changed. */
	operationId: number | null,
};

/**  What an import did. */
export type TagsImported = {
	/**  Tags made, or linked to a My Tag. */
	added: number,
	/**  Tags newly flagged as gone from rekordbox. */
	gone: number,
	/**  Flagged tags that rekordbox has again. */
	back: number,
	/**  Tracks given a tag. */
	applied: number,
	/**
	 *  My Tags left out: a name the writer can't carry, or one equal to
	 *  another My Tag's.
	 */
	skipped: number,
	/**  The operation this recorded; `None` when nothing changed. */
	operationId: number | null,
};

/**  One point of the target energy shape. */
export type TargetPoint = {
	/**  How far into the playlist, 0 (the first track) to 1 (the last). */
	at: number | null,
	/**
	 *  The energy wanted there, 1 to 10 (any number is taken and pulled
	 *  into that range; one that isn't a number drops the point).
	 */
	energy: number | null,
};

/**  Comparing text (a genre), letter case and outer spaces ignored. */
export type TextOp = "is" | "isNot" | "contains";

/**  Which way the tempo was read. */
export type TimeFeel = 
/**  As it is. */
"straight" | 
/**  The track is at half the selected track's tempo. */
"half" | 
/**  The track is at double the selected track's tempo. */
"double";

/**  A playlist's whole timeline. */
export type Timeline = {
	playlist: Playlist,
	entries: TimelineEntry[],
	/**  One fewer than the entries (none for fewer than two). */
	transitions: TimelineTransition[],
	/**  The sum of the known durations. */
	totalMs: number,
	/**  How many entries have no duration, which `total_ms` leaves out. */
	unknownDurations: number,
	/**  The target shape in order; empty with none. */
	target: TargetPoint[],
	/**  The tolerance the flags were judged by (the "what's next" setting). */
	tolerance: Tolerance,
};

/**  One entry of the timeline. */
export type TimelineEntry = {
	entryId: PlaylistEntryId,
	/**  From 0, dense. */
	position: number,
	recordingId: number,
	title: string | null,
	artist: string | null,
	durationMs: number | null,
	bpm: number | null,
	/**  Camelot (`8A`). */
	key: string | null,
	/**
	 *  The key is the app's own estimate (the table's `key_estimated`), shown
	 *  muted. Only marks the cell: the flags use `key` as it is.
	 */
	keyEstimated: boolean,
	/**  The energy the track shows (tags or the user's), 1 to 10. */
	energy: number | null,
	/**  When it starts, from the start of the playlist, in milliseconds. */
	startMs: number,
	/**  The target energy at this entry; none with no target. */
	target: number | null,
	/**  The entry's energy minus the target; none unless both are known. */
	gap: number | null,
};

/**  The step from entry i to entry i + 1. */
export type TimelineTransition = {
	fromEntry: PlaylistEntryId,
	toEntry: PlaylistEntryId,
	key: Flow,
	bpm: Flow,
	/**
	 *  The tempo difference, next minus this, read as half, as is or double
	 *  whichever is smallest (the "what's next" reading).
	 */
	bpmDelta: number | null,
	energy: Flow,
	/**  The next energy minus this. */
	energyStep: number | null,
};

/**  How far from the chosen track a fit may stray. */
export type Tolerance = 
/**  Sort by fit's thresholds: close blending. */
"tight" | 
/**  Bigger tempo, key and energy jumps still count. */
"wide";

/**  A Library track, as the preflight's lists name it. */
export type TrackLabel = {
	libraryTrack: LibraryTrackId,
	/**  `None` when the track has none; the list then shows the file's name. */
	title: string | null,
	artist: string | null,
	/**  The linked file's name, e.g. `a.mp3`. */
	fileName: string | null,
};

/**  Whether a node is under `Crates` or `Playlists`. */
export type TreeKind = "crate" | "playlist";

/**  Something changed since the operation that undo would overwrite. */
export type UndoConflict = {
	entity: string,
	/**  The row's id in `entity`. */
	entityId: number,
	/**  The field that changed since; null when the whole row is at issue. */
	field: string | null,
	problem: ConflictProblem,
};

/**  What undoing the newest operation did. */
export type UndoOutcome = 
/**  Every change of the operation was reversed. */
{ status: "undone"; operation: OperationInfo } | 
/**
 *  No operation is left to undo (or, when one operation was asked for,
 *  it isn't the next to undo).
 */
{ status: "nothingToUndo" } | 
/**  Undoing would overwrite later changes, so nothing was changed. */
{ status: "refused"; operation: OperationInfo; reason: UndoRefusal; conflicts: UndoConflict[] };

/**  Why a step can't be undone, as the UI says it. A code, never text. */
export type UndoRefusal = 
/**
 *  A track the step added has been sent to rekordbox since, or a field
 *  whose conflict the step settled.
 */
{ code: "sentSince" } | 
/**
 *  The step would put a Library track back, but the track or the file
 *  it was linked to is no longer in the database (its music folder was
 *  removed, or grouping merged the track away).
 */
{ code: "sourceGone" } | 
/**  The step would bring back a crate name another crate has now. */
{ code: "crateNameTaken"; name: string } | 
/**  Something the step changed has changed again since. */
{ code: "changedSince" } | 
/**
 *  The step switched a Library track's linked file so that the track
 *  goes to rekordbox as a new track, and the track has been sent since:
 *  the copy's entry is in rekordbox, and taking the switch back would
 *  leave it there with nothing to list it.
 */
{ code: "switchSentSince" } | 
/**
 *  The step merged Library tracks that are the same recording, and the
 *  track that stayed is linked to another file since (it followed its
 *  file to one the merge moved, or was switched): undoing the merge would
 *  leave two Library tracks on one file.
 */
{ code: "mergeLinkChanged" };

/**
 *  Review's group: tracks with no genre first, then the spellings no rule
 *  maps, most tracks first.
 */
export type UnmappedGenres = {
	noGenre: number,
	noGenreSample: NoGenreTrack[],
	spellings: Spelling[],
};

/**
 *  How a field's values are read and shown (and what a value given by hand
 *  looks like). The engine's own `Kind`, without its two never-listed
 *  members (an analysis field and `TrackID` never conflict).
 */
export type ValueKind = "location" | 
/**  rekordbox's six values, shown as stars. */
"rating" | 
/**  `0xRRGGBB`. */
"colour" | 
/**  `2026-09-28`. */
"date" | 
/**  Whole numbers. */
"number" | "text" | 
/**  A crate membership (`playlist:...`): `in` or `out`, shown in words. */
"membership";

/**  Where a value comes from. */
export type ValueOrigin = 
/**  rekordbox's entry for the track. */
"rekordboxEntry" | 
/**  A tag in one of the track's files (named in [`SourcedValue::file`]). */
"file";

/**
 *  The verdicts. Stored in `file_verdict.verdict` under [`Verdict::as_str`]
 *  (`clipped` is held back).
 */
export type Verdict = "ok" | "lowBitrate" | "suspectTranscode" | "truncated" | "broken";

/**  A group or a tag, for the commands that treat both alike. */
export type VocabItem = { kind: "group"; id: TagGroupId } | { kind: "tag"; id: TagId };

/**  Drives came or went: the music folders' `online` may have changed. */
export type VolumesChanged = null;

/**  What the app knows of a file's waveform. */
export type Waveform = 
/**
 *  The peaks: `peaks[i]` is the loudest sample of bucket `i` and
 *  `levels[i]` its RMS level, each 0 to 255.
 */
{ state: "ready"; peaks: number[]; levels: number[]; 
/**  The audio decoded, in milliseconds. */
durationMs: number } | 
/**  The job hasn't reached the file (or its audio just changed). */
{ state: "notReady" } | 
/**  The file can't be decoded, so there will be no waveform. */
{ state: "unavailable" };

/**  What a row can be offered to bring the file back. */
export type WayBack = 
/**  Clears the file's `hidden_reason` ("Show again"). */
"showAgain" | 
/**
 *  Makes the file the one its track shows ("Use this file instead",
 *  `hidden::choose`).
 */
"useThisFile" | 
/**
 *  Clears the file's `inbox_cleared` and puts it back in the Inbox ("Put
 *  back in Inbox"): the same command as "Show again".
 */
"putBack";

/**  Why a file is hidden (ROADMAP 1.11). */
export type Why = 
/**  The user hid it. */
"userHid" | 
/**  It was in the Inbox and the Inbox was cleared. */
"clearedInbox" | 
/**  An extra copy of a track whose best file is another file. */
"extraFile";

/**  One item of a wishlist with its result. */
export type WishItem = {
	id: number,
	wishlistId: number,
	position: number,
	artist: string,
	title: string,
	version: string | null,
	isrc: string | null,
	bought: boolean,
	notes: string | null,
	/**  The Inbox file that answered it (auto tick-off, 2.5). */
	acquiredFileId: number | null,
	acquiredAt: string | null,
	result: WishMatch,
};

/**  The items of a wishlist, or why they aren't given. */
export type WishItemsReply = { outcome: "items"; items: WishItem[] } | { outcome: "refused"; reason: WishlistRefusal };

/**  An item's result with its reason. */
export type WishMatch = {
	kind: WishMatchKind,
	reason: Reason,
	/**  The track it is about (the one owned, or the one reworked). */
	recordingId: number | null,
	/**  That track is in the Library (not only in All music). */
	inLibrary: boolean,
};

/**  What an item comes to. */
export type WishMatchKind = 
/**  A track you have. */
"owned" | 
/**  Another cut of it; counts as owned. */
"ownedOtherCut" | 
/**  A rework of it: a hint, not owned. */
"rework" | "missing";

/**  Why a line or row wasn't taken. */
export type WishSkipReason = 
/**  A pasted line with no " - " between an artist and a title. */
"noSeparator" | "missingArtist" | "missingTitle" | 
/**  A CSV row that couldn't be read. */
"unreadable";

/**  A line or row that wasn't taken. */
export type WishSkippedLine = {
	/**
	 *  Its line in the pasted text, or its row in the file (the header is
	 *  row 1), counting from 1.
	 */
	line: number,
	/**  What it said, cut to a short length. */
	text: string,
	reason: WishSkipReason,
};

/**  What a wishlist command came to. */
export type WishlistOutcome = 
/**  Done, as one operation (`None` when nothing changed). */
{ outcome: "done"; operationId: number | null; 
/**  The list it made or changed. */
wishlistId: number | null; 
/**  Items made. */
added: number; 
/**  Lines or rows an import couldn't take, each with where and why. */
skipped: WishSkippedLine[]; 
/**  How many in all; `skipped` keeps only the first few. */
skippedTotal: number } | 
/**  Nothing was written. */
{ outcome: "refused"; reason: WishlistRefusal };

/**  Why nothing was written. */
export type WishlistRefusal = "nameEmpty" | "nameTooLong" | "notesTooLong" | "noSuchWishlist" | "noSuchItem" | 
/**  The user hasn't turned wishlists on (Feature::Wishlist). */
"notTurnedOn" | 
/**  More items than [`MAX_ITEMS`]. */
"tooManyItems" | 
/**  The file couldn't be read, or isn't text. */
"fileUnreadable" | 
/**  The file is over [`MAX_FILE_BYTES`]. */
"fileTooBig" | 
/**  The pasted text is over [`MAX_TEXT_BYTES`]. */
"textTooBig" | 
/**  The CSV has no column naming the artist. */
"noArtistColumn" | 
/**  The CSV has no column naming the title. */
"noTitleColumn";

/**  Where a list came from, as stored. */
export type WishlistSource = "paste" | "csv";

/**  One wishlist with how its items come out. */
export type WishlistSummary = {
	id: number,
	name: string,
	source: WishlistSource,
	createdAt: string,
	total: number,
	owned: number,
	ownedOtherCut: number,
	rework: number,
	missing: number,
	/**  Items marked bought. */
	bought: number,
};

/**  The wishlists, or why they aren't given. */
export type WishlistsReply = { outcome: "lists"; lists: WishlistSummary[] } | { outcome: "refused"; reason: WishlistRefusal };

/**
 *  The answer to "how many tracks' stars would change", which the screen
 *  shows before the user turns the setting on.
 */
export type WouldChange = 
/**
 *  rekordbox's export was never read, so there's nothing to compare
 *  with. Not the same as no track changing.
 */
{ result: "noRead" } | 
/**
 *  The count, from rekordbox's values as of the newest read. Only a
 *  send's prepare step reads the export afresh, so the screen says how
 *  old this read is.
 */
{ result: "counted"; tracks: number; 
/**  When that read was made, as the database writes times. */
readAt: string };

/**  Everything the XML source screen shows. */
export type XmlSource = {
	/**  The export the user chose, if any. */
	path: string | null,
	watch: boolean,
	lastRead: LastRead | null,
	/**  Set when the newest read attempt failed. */
	lastFailure: ReadFailure | null,
	/**  With the watch on: an export newer than the last read, to offer. */
	newerExport: ExportFile | null,
	/**  rekordbox's default export folder (Documents), if Windows has one. */
	exportFolder: string | null,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

